        return Leaf(group[0])
    order = list(group)
    # Divide the band by area along its length.
    gtotal = sum(areas[g] for g in order) or 1.0
    cut_index = 1
    acc = 0.0
    for i, g in enumerate(order):
        acc += areas[g]
        if acc >= gtotal / 2:
