            return sum(areas[g] for g in u)

        def unit_tree(u: list[int]) -> Node:
            if len(u) == 1:
                return Leaf(u[0])
            a, b = u
            ratio = min(0.85, max(0.15, areas[a] / (areas[a] + areas[b])))
