            left, right = us[:cut_index], us[cut_index:]
            la = sum(unit_area(u) for u in left) or 1.0
            ra = sum(unit_area(u) for u in right) or 1.0
            return Split(
                vertical=road_along_y,     # cuts along the frontage
                ratio=min(0.88, max(0.12, la / (la + ra))),
                left=along(left),
                right=along(right),
