  };
  const stanceIdx = Math.max(0, Math.min(4, Math.round(n("vastu_slider", 2))));
  const vastu = (STANCES[stanceIdx] && STANCES[stanceIdx][1]) || "balanced";

  const amenities = [];
  if (d.get("amenity_pooja")) amenities.push("pooja");
