/* ═══ CROWN / TOP NAVIGATION BAR ════════════════════════════════════ */

.crown {
  position: fixed; inset: 0 0 auto 0; z-index: 50; height: var(--crown-h);
  display: flex; align-items: center;
  padding: 0 24px;
  background: rgba(7, 8, 11, 0.82);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border-bottom: 1px solid var(--rule);
}

.crown__inner {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
}

.mark {
  display: flex; align-items: center; gap: 12px;
  background: none; border: 0; cursor: pointer; padding: 6px 10px;
  border-radius: var(--r-sm);
  color: var(--chalk); flex: 0 0 auto;
  transition: opacity .18s var(--ease);
}
.mark:hover { opacity: 0.85; }

.mark__icon {
  width: 32px; height: 32px; border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(229, 169, 88, 0.25);
  box-shadow: 0 0 14px rgba(229, 169, 88, 0.12);
  display: grid; place-items: center;
  overflow: hidden;
}
.mark__logo-img {
  width: 22px; height: 22px;
  object-fit: contain;
  filter: brightness(1.15);
}

.mark__text { display: flex; align-items: center; gap: 8px; }
.mark__title { font-size: 15px; font-weight: 600; letter-spacing: -0.02em; }
.mark__title b { font-weight: 400; color: var(--chalk-3); margin-left: 2px; }
.mark__badge {
  font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em;
  padding: 2px 7px; border-radius: var(--r-pill);
  background: rgba(229, 169, 88, 0.08); color: var(--ochre);
  border: 1px solid rgba(229, 169, 88, 0.15);
}

.schemes { display: flex; gap: 6px; }
body[data-phase="compose"] .schemes,
body[data-phase="running"] .schemes { display: none; }

.scheme-tab {
  background: rgba(255,255,255,0.04); border: 1px solid var(--rule); border-radius: var(--r-sm);
  padding: 6px 14px; cursor: pointer; color: var(--chalk-3);
  font-size: 12px; font-weight: 500;
  display: flex; align-items: center; gap: 8px;
  transition: all .2s var(--ease);
}
.scheme-tab:hover { color: var(--chalk); background: rgba(255,255,255,0.08); border-color: rgba(255,255,255,0.2); }
.scheme-tab[aria-selected="true"] {
  background: var(--chalk); color: var(--earth); border-color: var(--chalk);
  box-shadow: 0 4px 14px rgba(255,255,255,0.18);
}
.scheme-tab b { font-family: var(--num); font-weight: 600; }

.views { display: flex; gap: 4px; margin-left: auto; }
body[data-phase="compose"] .views,
body[data-phase="running"] .views { display: none; }

.view-tab {
  background: none; border: 0; border-radius: var(--r-sm);
  padding: 7px 14px; cursor: pointer; color: var(--chalk-3);
  font-size: 12.5px; font-weight: 500; letter-spacing: -0.01em;
  transition: all .18s var(--ease);
}
.view-tab:hover { color: var(--chalk); background: rgba(255,255,255,0.05); }
.view-tab.is-on {
  color: var(--chalk); background: rgba(255,255,255,0.1);
  box-shadow: inset 0 1px 1px rgba(255,255,255,0.12);
}

.crown__end { display: flex; align-items: center; gap: 14px; flex: 0 0 auto; }
body[data-phase="compose"] .crown__end { margin-left: auto; }

.status-pill {
  display: flex; align-items: center; gap: 8px;
  padding: 5px 12px; border-radius: var(--r-pill);
  background: rgba(61, 214, 140, 0.08); border: 1px solid rgba(61, 214, 140, 0.2);
  font-size: 11.5px; font-weight: 500; color: var(--ok);
}
.status-pill__dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--ok);
  box-shadow: 0 0 10px var(--ok);
  animation: pulse-dot 2.5s infinite;
}
@keyframes pulse-dot { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(0.85); } }

.ghost-btn {
  background: rgba(255,255,255,0.05); border: 1px solid var(--rule); border-radius: var(--r-sm);
  padding: 7px 14px; cursor: pointer; color: var(--chalk-2);
  font-size: 12px; font-weight: 500;
  transition: all .18s var(--ease); white-space: nowrap;
}
.ghost-btn:hover { background: rgba(255,255,255,0.12); color: var(--chalk); border-color: rgba(255,255,255,0.25); }

.ledger {
  display: flex; align-items: center; gap: 7px;
  font-family: var(--num); font-size: 12px; color: var(--chalk-3);
  padding-left: 14px; border-left: 1px solid var(--rule);
}
.ledger b { color: var(--ok); font-weight: 600; }
.ledger__dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--ok);
}

/* ═══ PHASE SWITCHING ════════════════════════════════════════════════ */

.compose, .running, .review { display: none; }
body[data-phase="compose"] .compose { display: block; }
body[data-phase="running"] .running { display: grid; }
body[data-phase="review"]  .review  { display: grid; }

/* ═══ COMPOSE / FULL-WIDTH ARCHITECTURAL STUDIO ══════════════════════ */

.compose {
  position: fixed; inset: var(--crown-h) 0 0 0;
  background: var(--bg-base);
  overflow-y: auto;
}

/* ══════════════════════ BASIC RUNNING SCREEN ══════════════════════ */

.running {
  position: fixed;
  inset: var(--crown-h) 0 0 0;
  /* Visibility is the phase's to decide (see the body[data-phase] rules
     above). Declaring display here overrode them and pinned this screen
     over the brief the moment the intro ended. */
  place-items: center;
  padding: 4vh 4vw;
  overflow-y: auto;
  background: var(--bg-base);
  z-index: 5;
}

.running__inner {
  width: min(760px, 100%);
}

.running .sanskrit {
  margin: 0 0 6px;
  font-size: 13px;
  color: var(--ochre);
  font-weight: 600;
  letter-spacing: 0.04em;
}

.running h2 {
  margin: 0 0 20px;
  font-size: clamp(24px, 2.6vw, 32px);
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--chalk);
}

.run-track {
  height: 3px;
  border-radius: 3px;
  background: var(--rule);
  margin-bottom: 14px;
  overflow: hidden;
}

.run-track i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--indigo) 0%, var(--ochre) 100%);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .4s var(--ease);
}

.run-stage {
  margin: 0 0 24px;
  font-family: var(--num);
  font-size: 12.5px;
  color: var(--chalk-2);
}

.run-critics {
  display: none !important;
}

.run-log {
  font-family: var(--num);
  font-size: 11.5px;
  line-height: 1.85;
  color: var(--chalk-3);
  max-height: 28vh;
  overflow-y: auto;
  border-top: 1px solid var(--rule);
  padding-top: 14px;
}

.run-log p { margin: 0; }
.run-log b { color: var(--chalk-2); font-weight: 600; }

.run-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 14px;
}

/* ═══ REVIEW ═════════════════════════════════════════════════════════ */

.review {
  position: fixed; inset: var(--crown-h) 0 0 0;
  grid-template-columns: 280px minmax(0, 1fr) 300px;
  grid-template-rows: minmax(0, 1fr) auto;
}

.rail { overflow-y: auto; padding: 20px; min-width: 0; }
.rail--west { grid-column: 1; grid-row: 1; border-right: 1px solid var(--rule); }
.rail--east { grid-column: 3; grid-row: 1; border-left: 1px solid var(--rule); padding: 0; }

.rail__block { margin-bottom: 26px; }
.rail__block--flush { margin: 0; }
.rail__head {
  margin: 0 0 12px; font-size: 10.5px; font-weight: 700;
  letter-spacing: .19em; text-transform: uppercase; color: var(--chalk-3);
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
}
.rail--east .rail__head { padding: 20px 20px 12px; margin: 0; border-bottom: 1px solid var(--rule); }

.agree { font-family: var(--num); font-size: 11px; color: var(--ok); letter-spacing: 0; text-transform: none; }

.pick { margin: 0 0 6px; font-size: 19px; font-weight: 500; letter-spacing: -.01em; }
.pick__why { margin: 0; font-size: 12.5px; line-height: 1.65; color: var(--chalk-3); }

.kv { margin: 0; font-size: 12.5px; }
.kv div { display: flex; justify-content: space-between; gap: 10px; padding: 6px 0; border-bottom: 1px solid var(--rule); }
.kv dt { color: var(--chalk-3); }
.kv dd { margin: 0; font-family: var(--num); color: var(--chalk-2); text-align: right; }

.abar { margin-bottom: 11px; }
.abar__top { display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 4px; }
.abar__top span { color: var(--chalk-2); text-transform: capitalize; }
.abar__top b { font-family: var(--num); color: var(--chalk); font-weight: 600; }
.abar__t { height: 3px; background: var(--rule); overflow: hidden; }
.abar__t i { display: block; height: 100%; transform-origin: left; transform: scaleX(0); transition: transform .7s var(--ease); }

.critics { list-style: none; margin: 0; padding: 0; }
.cr {
  display: grid; grid-template-columns: 8px 1fr auto; gap: 3px 9px; align-items: center;
  padding: 11px 20px; border-bottom: 1px solid var(--rule); cursor: default;
  transition: background .16s var(--ease);
}
.cr:hover { background: var(--earth-2); }
.cr__g { width: 8px; height: 8px; transform: rotate(45deg); background: currentColor; grid-row: 1; }
.cr__n { grid-column: 2; font-size: 12.5px; color: var(--chalk); }
.cr__k { grid-column: 2; grid-row: 2; font-size: 9.5px; letter-spacing: .12em; text-transform: uppercase; color: var(--chalk-3); }
.cr__s { grid-column: 3; grid-row: 1 / span 2; font-family: var(--num); font-size: 15px; font-weight: 600; color: var(--chalk); }
.cr__b { grid-column: 2 / -1; grid-row: 3; height: 2px; background: var(--rule); margin-top: 5px; overflow: hidden; }
.cr__b i { display: block; height: 100%; background: currentColor; transform-origin: left; transform: scaleX(0); transition: transform .7s var(--ease); }
.cr[data-pig=indigo]{color:var(--indigo)} .cr[data-pig=hingula]{color:var(--hingula)}
.cr[data-pig=ochre]{color:var(--ochre)} .cr[data-pig=orpiment]{color:var(--orpiment)}
.cr.is-low { background: rgba(228,105,76,.06); }

/* ── stage ─────────────────────────────────────────────────────────── */

.stage { grid-column: 2; grid-row: 1; overflow: hidden; display: flex; min-width: 0; }
.pane { flex: 1; display: flex; flex-direction: column; min-width: 0; overflow: hidden; }
.pane[hidden] { display: none !important; }
}

.empty-note { color: var(--chalk-3); font-size: 13px; padding: 40px 0; text-align: center; }

/* ── verdict ───────────────────────────────────────────────────────── */

.verdict {
  grid-column: 1 / -1; grid-row: 2;
  display: grid; grid-template-columns: repeat(5, 1fr) auto;
