}
.v-cell { background: var(--sunk); padding: 11px 20px; border-top: 2px solid transparent; }
.v-cell[data-pig=indigo]{border-top-color:var(--indigo)} .v-cell[data-pig=orpiment]{border-top-color:var(--orpiment)}
.v-cell[data-pig=ochre]{border-top-color:var(--ochre)} .v-cell[data-pig=hingula]{border-top-color:var(--hingula)}
.v-cell[data-pig=chalk]{border-top-color:var(--chalk-3)}
.v-cell dt { font-size: 9.5px; letter-spacing: .16em; text-transform: uppercase; color: var(--chalk-3); }
.v-cell dd { margin: 2px 0 0; font-family: var(--num); font-size: 22px; font-weight: 600; letter-spacing: -.02em; line-height: 1.1; }
.v-cell small { font-family: var(--num); font-size: 10.5px; color: var(--chalk-3); }
.v-cell--act { display: grid; place-items: center; padding: 11px 20px; }

/* ── overlay ───────────────────────────────────────────────────────── */

.sheetover {
  position: fixed; inset: 0; z-index: 60; background: rgba(10,8,5,.72);
  backdrop-filter: blur(4px); display: grid; place-items: center; padding: 5vh 4vw;
  animation: fade .2s ease both;
}
@keyframes fade { from { opacity: 0 } }
.sheetover__panel {
  width: min(780px, 100%); max-height: 86vh; display: flex; flex-direction: column;
  background: var(--earth-2); border: 1px solid var(--rule-2); border-radius: var(--r);
  box-shadow: 0 30px 90px rgba(0,0,0,.6); animation: lift .3s var(--ease) both;
}
@keyframes lift { from { transform: translateY(14px); opacity: 0 } }
.sheetover__bar {
  display: flex; align-items: center; padding: 16px 22px; border-bottom: 1px solid var(--rule);
}
.sheetover__bar h2 { margin: 0; font-size: 11px; font-weight: 700; letter-spacing: .19em; text-transform: uppercase; color: var(--ochre); }
.x {
  margin-left: auto; background: none; border: 1px solid var(--rule-2); border-radius: var(--r);
  width: 28px; height: 28px; cursor: pointer; color: var(--chalk-3); display: grid; place-items: center;
}
.x:hover { color: var(--chalk); border-color: var(--chalk-3); }
.sheetover__body { overflow-y: auto; padding: 22px; }
.sheetover__body p { margin: 0 0 16px; font-size: 14.5px; line-height: 1.8; color: var(--chalk-2); max-width: 70ch; }

.toast {
  position: fixed; left: 50%; bottom: 22px; transform: translateX(-50%); z-index: 80;
  background: var(--earth-3); border: 1px solid var(--hingula); border-left-width: 2px;
  border-radius: var(--r); padding: 12px 18px; font-size: 13px; max-width: min(92vw, 66ch);
  box-shadow: 0 16px 40px rgba(0,0,0,.55); animation: lift .28s var(--ease) both;
}

/* ═══ RESPONSIVE ═════════════════════════════════════════════════════ */

@media (max-width: 1400px) {
  .review { grid-template-columns: 250px minmax(0, 1fr) 268px; }
}
@media (max-width: 1180px) {
  .compose { grid-template-columns: 1fr; overflow-y: auto; }
  .compose__diagram { border-right: 0; border-bottom: 1px solid var(--rule); padding: 30px; }
  .mandala-shell { width: min(52vh, 82%); }
  .review { grid-template-columns: minmax(0, 1fr) 268px; }
  .rail--west { display: none; }
  .stage { grid-column: 1; }
  .rail--east { grid-column: 2; }
  .verdict { grid-template-columns: repeat(3, 1fr); }
  .v-cell--act { grid-column: 1 / -1; }
  .mandala-review { grid-template-columns: 1fr; }
}
@media (max-width: 800px) {
  body { overflow: auto; }
  :root { --crown-h: auto; }
  .crown { position: sticky; flex-wrap: wrap; gap: 10px 14px; padding: 12px 16px; }
  .views { order: 5; width: 100%; margin-left: 0; overflow-x: auto; flex-wrap: nowrap; }
  .compose, .running, .review { position: static; height: auto; }
  .review { grid-template-columns: 1fr; }
  .rail--east { grid-column: 1; border-left: 0; border-top: 1px solid var(--rule); }
  .stage { grid-column: 1; height: 72vh; }
  .verdict { grid-template-columns: repeat(2, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

