/* ═══════════════════════════════════════════════════════════════════════
   Atelier

   The run, shown as the working session it is. Three draughtspeople draw
   the real candidate schemes room by room on the board while thirteen
   specialists read each sheet and say what they found; the principal
   chairs the vote. Nothing here is invented for effect: every plan drawn
   is the geometry the engine produced, and every line a person says is a
   message the engine emitted, attributed to the critic or stage that
   produced it.
   ═══════════════════════════════════════════════════════════════════════ */

const NS = "http://www.w3.org/2000/svg";
const reduced = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const easeOut = (t) => 1 - Math.pow(1 - t, 4);

/* ═══ THE PEOPLE ══════════════════════════════════════════════════════ */

export const PEOPLE = {
  "critic.compliance":    { name: "Rajesh Iyer",     role: "Building code",      pig: "hingula",  glyph: "code" },
  "critic.daylight":      { name: "Meera Nair",      role: "Daylight",           pig: "indigo",   glyph: "sun" },
  "critic.ventilation":   { name: "Arjun Rao",       role: "Ventilation",        pig: "indigo",   glyph: "wind" },
  "critic.privacy":       { name: "Kavya Menon",     role: "Privacy",            pig: "indigo",   glyph: "eye" },
  "critic.circulation":   { name: "Vikram Shah",     role: "Circulation",        pig: "indigo",   glyph: "path" },
  "critic.accessibility": { name: "Ananya Das",      role: "Accessibility",      pig: "indigo",   glyph: "access" },
  "critic.spatial":       { name: "Rohan Kapoor",    role: "Spatial quality",    pig: "indigo",   glyph: "frame" },
  "critic.structure":     { name: "Suresh Pillai",   role: "Structure",          pig: "ochre",    glyph: "column" },
  "critic.cost":          { name: "Farhan Qureshi",  role: "Quantity surveyor",  pig: "ochre",    glyph: "rupee" },
  "critic.vastu":         { name: "Lakshmi Sharma",  role: "Vastu",              pig: "orpiment", glyph: "mandala" },
  "critic.coherence":     { name: "Isha Banerjee",   role: "Design coherence",   pig: "orpiment", glyph: "compass" },
  "critic.brief":         { name: "Neha Joshi",      role: "Brief fidelity",     pig: "orpiment", glyph: "brief" },
  "critic.livability":    { name: "Priya Krishnan",  role: "Livability",         pig: "orpiment", glyph: "home" },
};

export const PRINCIPAL = { id: "principal", name: "Devika Raman", role: "Principal architect", pig: "gold", glyph: "seal" };

export const DRAFTERS = [
  { id: "d.sana",   name: "Sana Mirza",     role: "Drafting · living rooms",    pig: "gold", glyph: "pen", zone: "public" },
  { id: "d.nikhil", name: "Nikhil Verma",   role: "Drafting · services & core", pig: "gold", glyph: "pen", zone: "service" },
  { id: "d.tara",   name: "Tara Fernandes", role: "Drafting · private wing",    pig: "gold", glyph: "pen", zone: "private" },
];

export const GROUPS = [
  { title: "Code, structure & cost", ids: ["critic.compliance", "critic.structure", "critic.cost"] },
  { title: "Environment & use", ids: ["critic.daylight", "critic.ventilation", "critic.privacy",
    "critic.circulation", "critic.accessibility", "critic.spatial"] },
  { title: "Vastu & judgement", ids: ["critic.vastu", "critic.coherence", "critic.brief", "critic.livability"] },
];

const BY_ID = Object.fromEntries([
  ...Object.entries(PEOPLE).map(([id, p]) => [id, { id, ...p }]),
  [PRINCIPAL.id, PRINCIPAL],
  ...DRAFTERS.map((d) => [d.id, d]),
]);

/** A person by id, falling back to the committee charter for a critic this file does not know. */
export function person(id, charter = []) {
  if (BY_ID[id]) return BY_ID[id];
  const c = charter.find((x) => x.id === id);
  return { id, name: c?.name || id, role: c?.axis ? c.axis.replace(/_/g, " ") : "Specialist", pig: "chalk", glyph: "frame" };
}

export const firstName = (p) => p.name.split(" ")[0];

/* Discipline glyphs, authored on one 16-unit grid at one stroke weight. */
const GLYPHS = {
  code: "M2 3.5h4.2A1.8 1.8 0 0 1 8 5.3V13a1.6 1.6 0 0 0-1.6-1.4H2zM14 3.5H9.8A1.8 1.8 0 0 0 8 5.3V13a1.6 1.6 0 0 1 1.6-1.4H14z",
  sun: "M8 5.2a2.8 2.8 0 1 0 0 5.6 2.8 2.8 0 0 0 0-5.6zM8 1.6v1.6M8 12.8v1.6M1.6 8h1.6M12.8 8h1.6M3.5 3.5l1.1 1.1M11.4 11.4l1.1 1.1M3.5 12.5l1.1-1.1M11.4 4.6l1.1-1.1",
  wind: "M2 6h7.4A2 2 0 1 0 7.5 3.6M2 10.5h9.6a2 2 0 1 1-1.9 2.4M2 8.2h5",
