/* ═══════════════════════════════════════════════════════════════════════
   Atelier — the run as a drafting session, and the team in the review.
   Loaded after studio.css; inherits its tokens and pigments.
   ═══════════════════════════════════════════════════════════════════════ */

:root {
  --gold: #E5A958;
  --gold-hi: #EEBC72;
  --ink-dark: #17110A;
  --board: #0B0C10;
  --table: #07080B;
  --line: rgba(236, 239, 244, 0.88);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
}

/* ── people ─────────────────────────────────────────────────────────── */

[data-pig="indigo"]   { --pig: var(--indigo); }
[data-pig="hingula"]  { --pig: var(--hingula); }
[data-pig="ochre"]    { --pig: var(--ochre); }
[data-pig="orpiment"] { --pig: var(--orpiment); }
[data-pig="gold"]     { --pig: var(--gold); }
[data-pig="chalk"]    { --pig: var(--chalk-3); }

.av {
  --pig: var(--chalk-3);
  position: relative; flex: 0 0 auto;
  width: var(--av, 32px); height: var(--av, 32px); border-radius: 50%;
  display: grid; place-items: center;
  background: color-mix(in srgb, var(--pig) 15%, #0B0C10);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pig) 50%, transparent);
  color: var(--pig);
}
.av[data-pig] { --pig: inherit; }
.av[data-pig="indigo"]   { --pig: var(--indigo); }
.av[data-pig="hingula"]  { --pig: var(--hingula); }
.av[data-pig="ochre"]    { --pig: var(--ochre); }
.av[data-pig="orpiment"] { --pig: var(--orpiment); }
.av[data-pig="gold"]     { --pig: var(--gold); }
.av[data-pig="chalk"]    { --pig: var(--chalk-3); }
.av__i {
  font-size: calc(var(--av, 32px) * 0.36); font-weight: 600;
  letter-spacing: 0.02em; line-height: 1; color: color-mix(in srgb, var(--pig) 88%, white);
}
.av__b {
  position: absolute; right: -3px; bottom: -3px;
  width: calc(var(--av, 32px) * 0.5); height: calc(var(--av, 32px) * 0.5);
  border-radius: 50%; display: grid; place-items: center;
  background: #0B0C10;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pig) 45%, transparent);
}
.gl { width: 68%; height: 68%; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }

/* ── the running phase ──────────────────────────────────────────────── */

.running {
  position: fixed; inset: var(--crown-h) 0 0 0; z-index: 5;
  padding: 0; overflow: hidden;
  background: #050608;
}
body[data-phase="running"] .running { display: block; }

.atelier { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); }

.at-head {
  display: grid; grid-template-columns: minmax(260px, auto) minmax(0, 1fr) auto;
  align-items: center; gap: 28px;
  padding: 16px 28px; border-bottom: 1px solid var(--rule);
}
.at-title h2 {
