/* the conversation */
.at-talk { display: flex; flex-direction: column; height: 176px; min-height: 0; }
.at-talk__h {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px;
  font-size: 12.5px; font-weight: 600; color: var(--chalk-2);
}
.at-live { display: flex; align-items: center; gap: 7px; font-size: 11.5px; font-weight: 500; color: var(--chalk-3); }
.at-live::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--chalk-4); }
