.sh-dim { fill: none; stroke: rgba(236, 239, 244, 0.42); stroke-width: calc(1px * var(--k)); }
.sh-dimtext { fill: var(--chalk-3); font-family: var(--num) !important; font-size: calc(10px * var(--k)); text-anchor: middle; }
.sh-ltitle { fill: var(--chalk-2); font-size: calc(10.5px * var(--k)); font-weight: 600; letter-spacing: 0.12em; }
.sh-north path { fill: var(--chalk-2); }
.sh-north text { fill: var(--chalk-3); font-size: calc(10px * var(--k)); font-weight: 600; text-anchor: middle; }

.sh-fill { stroke: none; }
.sh-fill.t-public  { fill: rgba(229, 169, 88, 0.085); }
.sh-fill.t-service { fill: rgba(127, 163, 212, 0.06); }
.sh-fill.t-wet     { fill: rgba(127, 163, 212, 0.13); }
.sh-fill.t-private { fill: rgba(243, 208, 99, 0.06); }
.sh-line { fill: none; stroke: var(--line); stroke-width: calc(1.2px * var(--k)); stroke-linejoin: round; stroke-linecap: round; }
.sh-wall { fill: none; stroke: rgba(236, 239, 244, 0.9); stroke-linecap: square; }
.sh-wall--ext { stroke: #F1F3F6; }
.sh-cut { fill: none; stroke: var(--board); stroke-linecap: butt; }
.sh-door { fill: none; stroke: rgba(236, 239, 244, 0.85); stroke-width: calc(1.1px * var(--k)); }
.sh-swing { fill: none; stroke: rgba(236, 239, 244, 0.38); stroke-width: calc(0.9px * var(--k)); stroke-dasharray: calc(3px * var(--k)) calc(3px * var(--k)); }
.sh-glaze { fill: none; stroke: var(--indigo); stroke-width: calc(1.1px * var(--k)); }
.sh-label text { text-anchor: middle; }
.sh-name { fill: var(--chalk); font-size: calc(9.5px * var(--k)); font-weight: 600; letter-spacing: 0.06em; }
.sh-name--sm { font-size: calc(7.5px * var(--k)); }
.sh-area { fill: var(--chalk-3); font-family: var(--num) !important; font-size: calc(8.5px * var(--k)); }

/* ── the review: the team keeps what it said ────────────────────────── */

.chair {
  display: flex; align-items: center; gap: 9px; margin: 0; padding: 10px 20px;
  font-size: 12px; color: var(--chalk-3); border-bottom: 1px solid var(--rule);
}
.critics { list-style: none; margin: 0; padding: 0; }
.tm { border-bottom: 1px solid var(--rule); }
.tm[data-pig="indigo"]   { --pig: var(--indigo); }
.tm[data-pig="hingula"]  { --pig: var(--hingula); }
.tm[data-pig="ochre"]    { --pig: var(--ochre); }
.tm[data-pig="orpiment"] { --pig: var(--orpiment); }
.tm__head {
  width: 100%; display: grid; grid-template-columns: 32px minmax(0, 1fr) auto; gap: 11px; align-items: center;
  padding: 13px 18px 3px; border: 0; background: none; color: inherit; text-align: left; cursor: pointer;
  transition: background-color 0.2s var(--ease-out);
}
.tm__head:hover { background: rgba(255, 255, 255, 0.025); }
.tm__who { min-width: 0; }
.tm__who b { display: block; font-size: 13px; font-weight: 600; color: var(--chalk); }
.tm__who small { display: block; font-size: 11.5px; color: var(--chalk-3); }
.tm__sc { font-family: var(--num); font-size: 15px; font-weight: 600; color: var(--chalk); font-variant-numeric: tabular-nums; }
.tm[data-low="1"] .tm__sc { color: var(--hingula); }
.tm__line {
  margin: 3px 18px 0 61px; font-size: 12.5px; line-height: 1.5; color: var(--chalk-2);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.tm__line:empty { display: none; }
.tm.is-open .tm__line { -webkit-line-clamp: unset; display: block; }
.tm__bar { display: block; height: 2px; margin: 9px 18px 12px 61px; border-radius: 2px; background: var(--rule); overflow: hidden; }
.tm__bar i {
  display: block; height: 100%; background: var(--pig, var(--indigo));
  transform-origin: left; transform: scaleX(0); transition: transform 0.8s var(--ease-out);
}
.tm[data-low="1"] .tm__bar i { background: var(--hingula); }
.tm__more { margin: -2px 18px 14px 61px; font-size: 12px; line-height: 1.55; color: var(--chalk-3); }
.tm__more p { margin: 0 0 7px; }
.tm__more:not([hidden]) { animation: at-rise 0.3s var(--ease-out) both; }
.tm__finding { color: var(--chalk-2); }
.sev {
  font-family: var(--num); font-size: 10px; font-weight: 600; text-transform: capitalize;
  padding: 1px 6px; border-radius: 4px; background: rgba(255, 255, 255, 0.06); color: var(--chalk-2);
}
.sev[data-sev="moderate"] { color: var(--ochre); background: rgba(229, 169, 88, 0.12); }
.sev[data-sev="major"], .sev[data-sev="critical"] { color: var(--hingula); background: rgba(240, 101, 72, 0.12); }
.tm__fix { color: var(--chalk-2); }
.tm__fix::before { content: "Suggests: "; color: var(--gold); font-weight: 600; }

.credits { display: flex; flex-direction: column; gap: 9px; margin-top: 16px; }
.credit { display: flex; align-items: center; gap: 10px; font-size: 12px; line-height: 1.35; color: var(--chalk-3); }
.credit__stack { display: flex; flex: 0 0 auto; }
.credit__stack .av { box-shadow: 0 0 0 2px #050608, inset 0 0 0 1px color-mix(in srgb, var(--pig) 50%, transparent); }
.credit__stack > * + * { margin-left: -7px; }
.credit__more {
  height: 24px; min-width: 26px; padding: 0 6px; border-radius: 12px;
  display: grid; place-items: center; font-family: var(--num); font-size: 10px; font-weight: 600;
  color: var(--chalk-2); background: #15171C; box-shadow: 0 0 0 2px #050608;
}

/* the plate receives the drawn sheet during the hand-off */
body[data-phase="review"] .plate { view-transition-name: sheet; }
.plate .plate__ghost { width: 100%; height: 100%; max-height: none; display: block; }

/* ── phase transitions ──────────────────────────────────────────────── */

.crown { view-transition-name: crown; }
::view-transition-old(root) { animation: at-vt-out 0.3s cubic-bezier(0.4, 0, 1, 1) both; }
::view-transition-new(root) { animation: at-vt-in 0.5s var(--ease-out) both; }
::view-transition-group(sheet) { animation-duration: 0.72s; animation-timing-function: cubic-bezier(0.2, 0.75, 0.2, 1); }
::view-transition-old(sheet),
::view-transition-new(sheet) { height: 100%; object-fit: contain; }
::view-transition-group(crown) { animation-duration: 0.4s; }
@keyframes at-vt-out { to { opacity: 0; transform: scale(0.988); } }
@keyframes at-vt-in { from { opacity: 0; transform: scale(1.01); } }

/* ── smaller screens ────────────────────────────────────────────────── */

@media (max-width: 1240px) {
  .at-body { grid-template-columns: minmax(0, 1fr) 340px; }
  .at-stages li { padding: 0 8px; font-size: 11.5px; }
}

@media (max-width: 1100px) {
  .running { overflow-y: auto; }
  .atelier { height: auto; min-height: 100%; }
  .at-head { grid-template-columns: minmax(0, 1fr) auto; gap: 12px 20px; }
  .at-stages { grid-column: 1 / -1; order: 3; justify-content: flex-start; overflow-x: auto; padding-bottom: 2px; }
  .at-stages li:first-child { padding-left: 0; }
  .at-body { grid-template-columns: minmax(0, 1fr); }
  .at-board { height: min(64vh, 600px); }
  .at-table { border-left: 0; border-top: 1px solid var(--rule); overflow: visible; }
  .at-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (max-width: 680px) {
  .at-head { padding: 14px 16px; }
  .at-title h2 { font-size: 18px; }
  .at-work { padding: 14px 16px 16px; }
  .at-rack { overflow-x: auto; }
  .at-scheme { flex: 0 0 auto; }
  .at-board { height: 58vh; }
  .at-sheetwrap { inset: 12px 12px 52px; }
  .at-tblock { display: none; }
  .at-legend { left: 14px; bottom: 12px; max-width: calc(100% - 28px); gap: 4px 12px; font-size: 11px; }
  .at-talk { height: 196px; }
  .at-table { padding: 16px; }
  .at-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .at-stages li[data-state="active"] i::after,
  .at-tile[data-state="reading"] .av::after,
  .at-live[data-on="1"]::before { animation: none; }
  .at-scheme, #at-open:not([hidden]), .tm__more:not([hidden]) { animation: none; }
}

