/* ═══════════════════════════════════════════════════════════════════════
   Stage3D — the drafting table as a small 3D model.

   A team of three works the plot for the whole run: the engineer stakes
   the corners and walks the boundary, one architect chalks the setbacks,
   the other sketches the zoning, and they keep laying out the column grid
   until the engine returns its schemes. Then they draw the real plan room
   by room by walking each outline, the walls rise, and the camera settles
   to plan view for the hand-off into the review. Every line drawn after
   the planning sketch is the engine's own geometry.
   ═══════════════════════════════════════════════════════════════════════ */

import * as THREE from "three";

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const reduced = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const GAP = 3.6;          // metres between floor plates
const WALL_H = 1.05;      // cut-away height: a model, not a building
const RUN = 3.4;          // m/s
const PACE = 1.7;         // m/s while drawing

const COL = {
  ground: 0x0b0c10, plot: 0x111318, line: 0xe8ebf0, chalk: 0x8d94a5,
  gold: 0xe5a958, indigo: 0x7fa3d4, wall: 0xe9ecf1, glass: 0x7fa3d4,
  public: 0xe5a958, service: 0x7fa3d4, wet: 0x7fa3d4, private: 0xf3d063,
};

const PUBLIC = new Set(["foyer", "living", "dining", "puja", "verandah", "garage", "drawing", "family", "lobby", "home_office"]);
const PRIVATE = new Set(["master_bedroom", "bedroom", "guest_bedroom", "children_bedroom", "study", "balcony", "terrace", "wardrobe", "servant"]);
const WET = new Set(["bathroom", "toilet", "powder", "utility", "laundry"]);
const zoneOf = (t) => (PUBLIC.has(t) ? "public" : PRIVATE.has(t) ? "private" : "service");
const tintOf = (t) => (PUBLIC.has(t) ? "public" : PRIVATE.has(t) ? "private" : WET.has(t) ? "wet" : "service");

export function webglAvailable() {
  try {
    const c = document.createElement("canvas");
    return !!(c.getContext("webgl2") || c.getContext("webgl"));
  } catch { return false; }
}

/* ── geometry helpers ─────────────────────────────────────────────────── */

// Points along a polyline every `step` metres, so a line can be revealed
// at the pace someone walks it.
function resample(pts, step = 0.08, closed = false) {
  const src = closed ? [...pts, pts[0]] : pts;
  const out = [src[0].clone()];
  for (let i = 1; i < src.length; i++) {
    const a = src[i - 1], b = src[i];
    const n = Math.max(1, Math.ceil(a.distanceTo(b) / step));
    for (let k = 1; k <= n; k++) out.push(a.clone().lerp(b, k / n));
  }
  return out;
}

function lineOf(points, color, opacity = 1, y = 0.02) {
  const pos = new Float32Array(points.length * 3);
  points.forEach((p, i) => { pos[i * 3] = p.x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = p.z; });
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setDrawRange(0, 0);
  const m = new THREE.LineBasicMaterial({ color, transparent: true, opacity });
  const line = new THREE.Line(g, m);
  line.userData.count = points.length;
  return line;
}

function plane(w, d, color, opacity) {
  const m = new THREE.MeshStandardMaterial({ color, transparent: true, opacity, roughness: 1, metalness: 0, depthWrite: false });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, d), m);
  mesh.rotation.x = -Math.PI / 2;
  return mesh;
}

function shapeFill(pts, color, opacity) {
  const s = new THREE.Shape(pts.map((p) => new THREE.Vector2(p.x, -p.z)));
  const g = new THREE.ShapeGeometry(s);
  const m = new THREE.MeshBasicMaterial({ color, transparent: true, opacity, depthWrite: false });
  const mesh = new THREE.Mesh(g, m);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.012;
  return mesh;
}

/* ── the figures ──────────────────────────────────────────────────────── */

const LOOKS = {
  arch1: { shirt: 0xe4e8ef, legs: 0x3b4252, skin: 0xb98463, hair: 0x1b1511, tool: "pencil" },
  eng:   { shirt: 0xe8792f, legs: 0x4a4e5c, skin: 0xc99a75, hat: 0xf2b33d, tool: "staff" },
  arch2: { shirt: 0x7fa3d4, legs: 0x2e3442, skin: 0x8d5a3b, hair: 0x14100d, tool: "pencil" },
};

function mat(color, rough = 0.7) {
  return new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: 0.02 });
}

function buildFigure(kind) {
  const L = LOOKS[kind];
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const limb = (r, len, color) => {
    const g = new THREE.Group();
    const m = new THREE.Mesh(new THREE.CapsuleGeometry(r, len, 4, 8), mat(color));
    m.position.y = -(len / 2 + r);
    m.castShadow = true;
    g.add(m);
    return g;
  };

  const legL = limb(0.055, 0.34, L.legs); legL.position.set(-0.07, 0.48, 0);
  const legR = limb(0.055, 0.34, L.legs); legR.position.set(0.07, 0.48, 0);
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.135, 0.26, 4, 10), mat(L.shirt, 0.8));
  torso.position.y = 0.66; torso.castShadow = true;
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.105, 16, 12), mat(L.skin, 0.6));
  head.position.y = 0.98; head.castShadow = true;
  const armL = limb(0.04, 0.26, L.shirt); armL.position.set(-0.17, 0.82, 0);
  const armR = limb(0.04, 0.26, L.shirt); armR.position.set(0.17, 0.82, 0);
  body.add(legL, legR, torso, head, armL, armR);

  if (L.hat) {
    const dome = new THREE.Mesh(new THREE.SphereGeometry(0.118, 16, 8, 0, TAU, 0, Math.PI / 2), mat(L.hat, 0.45));
    dome.position.y = 1.0;
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 0.014, 20), mat(L.hat, 0.45));
    brim.position.y = 1.0;
    body.add(dome, brim);
  } else {
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.11, 16, 8, 0, TAU, 0, Math.PI * 0.55), mat(L.hair, 0.9));
    hair.position.y = 0.995; hair.rotation.x = -0.25;
    body.add(hair);
  }

  // The tool, in the right hand.
  const tool = new THREE.Group();
  if (L.tool === "pencil") {
    const p = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.2, 6), mat(COL.gold, 0.4));
    p.position.y = -0.1;
    tool.add(p);
  } else {
    const s = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.95, 6), mat(0xf2b33d, 0.5));
    s.position.y = -0.2;
    tool.add(s);
  }
  tool.position.y = -0.33;
  armR.add(tool);

  root.scale.setScalar(0.92);
  root.userData = { legL, legR, armL, armR, body, phase: Math.random() * TAU };
  return root;
}

/* ═══ THE STAGE ═════════════════════════════════════════════════════════ */

export class Stage3D {
  constructor(host) {
    this.host = host;
    this.speed = 1;
    this.static = reduced();
    this.labels = [];
    this.schemes = {};
    this.raf = 0;
    this.t0 = performance.now();

    const r = (this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: "high-performance" }));
    r.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    r.outputColorSpace = THREE.SRGBColorSpace;
    r.toneMapping = THREE.ACESFilmicToneMapping;
    r.toneMappingExposure = 1.05;
    r.shadowMap.enabled = true;
    r.shadowMap.type = THREE.PCFSoftShadowMap;
    r.setClearColor(COL.ground, 1);
    r.domElement.className = "st-canvas";
    host.append(r.domElement);

    this.labelLayer = document.createElement("div");
    this.labelLayer.className = "st-labels";
    host.append(this.labelLayer);

    const scene = (this.scene = new THREE.Scene());
    scene.fog = new THREE.Fog(COL.ground, 60, 140);
    scene.add(new THREE.HemisphereLight(0xc8d6ff, 0x241c14, 0.85));
    const sun = (this.sun = new THREE.DirectionalLight(0xfff2e0, 1.7));
    sun.castShadow = true;
    sun.shadow.mapSize.set(1024, 1024);
    sun.shadow.bias = -0.0008;
    sun.shadow.radius = 4;
    scene.add(sun, sun.target);

    const ground = new THREE.Mesh(new THREE.PlaneGeometry(400, 400), new THREE.MeshStandardMaterial({ color: COL.ground, roughness: 1 }));
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    this.camera = new THREE.OrthographicCamera(-10, 10, 10, -10, 0.1, 400);
    this.view = { tilt: 1, target: new THREE.Vector3(), size: 12, drift: 0 };
    this.root = new THREE.Group();
    scene.add(this.root);

    this.team = ["arch1", "eng", "arch2"].map((k, i) => {
      const fig = buildFigure(k);
      fig.position.set(-30, 0, 4 + i);
      fig.visible = !this.static;
      scene.add(fig);
      return { kind: k, fig, tasks: [], task: null, pos: fig.position, face: 0, mode: "idle", busyUntil: 0 };
    });

    this._resize = () => this.resize();
    this.ro = new ResizeObserver(this._resize);
    this.ro.observe(host);
    this.resize();
    this._tick = this._tick.bind(this);
    this.raf = requestAnimationFrame(this._tick);
  }

  /* ── framing ──────────────────────────────────────────────────────── */

  resize() {
    const w = this.host.clientWidth, h = this.host.clientHeight;
    if (!w || !h) return;
    this.renderer.setSize(w, h, false);
    this.aspect = w / h;
    this._frame();
  }

  _frame() {
    const c = this.camera, v = this.view;
    const s = v.size;
    c.left = -s * this.aspect; c.right = s * this.aspect; c.top = s; c.bottom = -s;
    c.updateProjectionMatrix();
  }

  // Place the camera: isometric while the team works, straight down for
  // the hand-off. `tilt` runs 1 (iso) to 0 (plan).
  _placeCamera(now) {
    const v = this.view;
    const drift = this.static ? 0 : Math.sin(now / 9000) * 0.11 * v.tilt;
    const yaw = -Math.PI / 4 * 0.62 * v.tilt + drift;
    const elev = lerp(Math.PI / 2 - 0.0001, 0.68, v.tilt);
    const r = 80;
    this.camera.position.set(
      v.target.x + r * Math.cos(elev) * Math.sin(yaw),
      v.target.y + r * Math.sin(elev),
      v.target.z + r * Math.cos(elev) * Math.cos(yaw),
    );
    this.camera.up.set(0, 1, 0);
    if (v.tilt < 0.02) this.camera.up.set(0, 0, -1);
    this.camera.lookAt(v.target);
  }

  /* ── the plot ─────────────────────────────────────────────────────── */

  // Lay out floor plates for a plot of w x d metres with n levels.
  setPlot({ w, d, levels = 1, road = "N", setbacks = null }) {
    this.root.clear();
    this.labels.forEach((l) => l.el.remove());
    this.labels = [];
    this.schemes = {};
    this.plot = { w, d, n: Math.max(1, levels), road };
    const total = this.plot.n * w + (this.plot.n - 1) * GAP;
    this.origin = new THREE.Vector3(-total / 2, 0, d / 2);   // plan (0,0) of plate 0
    this.view.target.set(0, 0, 0);
    this.view.size = Math.max(total / Math.max(this.aspect || 1.6, 0.6), d) * 0.62 + 2.2;
    this._frame();

    const sun = this.sun;
    sun.position.set(-14, 26, 18);
    sun.target.position.set(0, 0, 0);
    const sc = sun.shadow.camera;
    sc.left = -total; sc.right = total; sc.top = d + 6; sc.bottom = -d - 6;
    sc.updateProjectionMatrix();

    this.plates = [];
    for (let i = 0; i < this.plot.n; i++) {
      const g = new THREE.Group();
      g.position.copy(this.P(i, 0, 0));
      const surf = plane(w, d, COL.plot, i === 0 ? 0.9 : 0.55);
      surf.position.set(w / 2, 0.004, -d / 2);
      surf.receiveShadow = true;
      g.add(surf);
      this.root.add(g);
      this.plates.push(g);
    }

    // The planning layer: everything the team sketches before a scheme exists.
    this.planning = new THREE.Group();
    this.root.add(this.planning);
    this.setbacks = setbacks;
    this.construction = [];
  }

  // Plan coordinates on level i to world space.
  P(i, x, y) {
    const { w } = this.plot;
    return new THREE.Vector3(this.origin.x + i * (w + GAP) + x, 0, this.origin.z - y);
  }

  /* ── labels ───────────────────────────────────────────────────────── */

  _label(text, world, cls = "") {
    const el = document.createElement("span");
    el.className = `st-label ${cls}`;
    el.textContent = text;
    this.labelLayer.append(el);
    const l = { el, world: world.clone(), on: false };
    this.labels.push(l);
    return l;
  }

  _show(l, on = true) {
    l.on = on;
    l.el.classList.toggle("is-on", on);
  }

  /* ── tasks ────────────────────────────────────────────────────────── */

  _do(who, ...tasks) { who.tasks.push(...tasks); }
  _member(kind) { return this.team.find((t) => t.kind === kind); }

  // The first minutes on site: stake it out, chalk the setbacks, zone it.
  plan(brief) {
    const { w, d, n } = this.plot;
    const eng = this._member("eng"), a1 = this._member("arch1"), a2 = this._member("arch2");
    this.team.forEach((t, i) => { t.fig.position.copy(this.P(0, -6 - i * 1.2, d * 0.3 + i)); t.tasks = []; t.task = null; });

    for (let i = 0; i < n; i++) {
      // Corner stakes, and the boundary walked between them.
      const corners = [[0, 0], [w, 0], [w, d], [0, d]].map(([x, y]) => this.P(i, x, y));
      this._do(eng, { type: "run", to: corners[0] });
      corners.forEach((c, k) => {
        this._do(eng, { type: "call", fn: () => this._stake(c) });
        const next = corners[(k + 1) % 4];
        this._do(eng, { type: "draw", pts: resample([c, next]), line: this._line([c, next], COL.line, i === 0 ? 0.55 : 0.28) });
      });
    }

    // Setbacks, chalked in gold on the ground plate.
    const sb = this.setbacks;
    if (sb) {
      const r = this.plot.road;
      const inset = r === "N" ? { t: sb.front, b: sb.rear, l: sb.left, r: sb.right }
        : r === "S" ? { t: sb.rear, b: sb.front, l: sb.right, r: sb.left }
          : r === "E" ? { t: sb.left, b: sb.right, l: sb.rear, r: sb.front }
            : { t: sb.right, b: sb.left, l: sb.front, r: sb.rear };
      const pts = [[inset.l, inset.b], [w - inset.r, inset.b], [w - inset.r, d - inset.t], [inset.l, d - inset.t], [inset.l, inset.b]]
        .map(([x, y]) => this.P(0, x, y));
      this._do(a1, { type: "wait", t: 0.6 }, { type: "run", to: pts[0] });
      for (let k = 1; k < pts.length; k++) {
        this._do(a1, { type: "draw", pts: resample([pts[k - 1], pts[k]]), line: this._line([pts[k - 1], pts[k]], COL.gold, 0.5) });
      }
    }

    // Zoning: living to the road, services behind, bedrooms to the back
    // (or upstairs) - the arrangement the generator itself starts from.
    const zones = n > 1
      ? [[0, "Living & arrival", 0.0, 0.45, COL.public], [0, "Kitchen & services", 0.45, 1.0, COL.service], [1, "Bedrooms", 0.0, 1.0, COL.private]]
      : [[0, "Living & arrival", 0.0, 0.36, COL.public], [0, "Kitchen & services", 0.36, 0.6, COL.service], [0, "Bedrooms", 0.6, 1.0, COL.private]];
    this._do(a2, { type: "wait", t: 1.2 });
    for (const [lv, name, f0, f1, color] of zones) {
      const m = 1.0;
      const y0 = this._depth(f1), y1 = this._depth(f0);
      const lo = Math.min(y0, y1) + m * 0.5, hi = Math.max(y0, y1) - m * 0.5;
      const rect = [[m, lo], [w - m, lo], [w - m, hi], [m, hi], [m, lo]].map(([x, y]) => this.P(lv, x, y));
      this._do(a2, { type: "run", to: rect[0] });
      const fill = shapeFill(rect.slice(0, 4), color, 0);
      this.planning.add(fill);
      for (let k = 1; k < rect.length; k++) {
        this._do(a2, { type: "draw", pts: resample([rect[k - 1], rect[k]]), line: this._line([rect[k - 1], rect[k]], color, 0.6, this.planning) });
      }
      const centre = rect.slice(0, 4).reduce((a, p) => a.add(p), new THREE.Vector3()).multiplyScalar(0.25);
      const lab = this._label(name, centre, "st-label--zone");
      this._do(a2, { type: "call", fn: () => { this._fade(fill.material, 0.07, 500); this._show(lab); } });
    }

    // Then the column grid, line by line, until the schemes arrive.
    for (let i = 0; i < n; i++) {
      for (let x = 3.8; x < w - 0.5; x += 3.8) this.construction.push([this.P(i, x, 0.3), this.P(i, x, d - 0.3)]);
      for (let y = 3.8; y < d - 0.5; y += 3.8) this.construction.push([this.P(i, 0.3, y), this.P(i, w - 0.3, y)]);
    }
    this.planningActive = true;
  }

  // Fraction of depth from the road (0) to the rear (1), as a plan y.
  _depth(f) {
    const { d, road } = this.plot;
    return road === "S" ? f * d : d - f * d;
  }

  _line(pts, color, opacity, parent = this.root) {
    const line = lineOf(resample(pts), color, opacity);
    parent.add(line);
    return line;
  }

  _stake(at) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.5, 8), mat(0xe9ecf1));
    post.position.set(at.x, 0.25, at.z);
    post.castShadow = true;
    const cap = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.12, 10), mat(0xe8792f, 0.5));
    cap.position.set(at.x, 0.56, at.z);
    const g = new THREE.Group();
    g.add(post, cap);
    g.scale.setScalar(0.01);
    this.root.add(g);
    this._tween(400, (k) => g.scale.setScalar(Math.max(0.01, ease(k))));
  }

  /* ── the schemes ──────────────────────────────────────────────────── */

  // Build a scheme's geometry (hidden) so it can be drawn on demand.
  addScheme(sk) {
    if (this.schemes[sk.id]) return this.schemes[sk.id];
    const group = new THREE.Group();
    group.visible = false;
    this.root.add(group);
    const rooms = [];
    const walls = [];
    sk.levels.forEach((lv, li) => {
      if (li >= this.plot.n) return;
      for (const room of lv.rooms) {
        const pts = room.poly.map((p) => this.P(li, p[0], p[1]));
        const line = lineOf(resample(pts, 0.08, true), COL.line, 0.9, 0.03);
        const fill = shapeFill(pts, COL[tintOf(room.type)], 0);
        group.add(fill, line);
        const c = pts.reduce((a, p) => a.add(p), new THREE.Vector3()).multiplyScalar(1 / pts.length);
        const lab = this._label(`${room.name}`, c, "st-label--room");
        lab.scheme = sk.id;
        rooms.push({ room, li, pts, line, fill, lab, centre: c, zone: zoneOf(room.type), drawn: false });
      }
      for (const w of lv.walls) walls.push(...this._wallPieces(group, li, w));
    });
    const s = { sk, group, rooms, walls, drawn: false, risen: false };
    this.schemes[sk.id] = s;
    return s;
  }

  // A wall as boxes between its openings; glazing as a pane in the gap.
  _wallPieces(group, li, w) {
    const a = this.P(li, w.a[0], w.a[1]), b = this.P(li, w.b[0], w.b[1]);
    const len = a.distanceTo(b);
    if (len < 0.05) return [];
    const dir = b.clone().sub(a).normalize();
    const cuts = w.open.map((o) => [clamp(o.p * len - o.w / 2, 0, len), clamp(o.p * len + o.w / 2, 0, len), o.k])
      .sort((x, y) => x[0] - y[0]);
    const spans = [];
    let at = 0;
    for (const [s0, s1] of cuts) { if (s0 > at) spans.push([at, s0]); at = Math.max(at, s1); }
    if (at < len) spans.push([at, len]);
    const t = Math.max(0.1, w.t);
    const wm = mat(w.ext ? COL.wall : 0xd6dae2, 0.85);
    const out = [];
    const angle = Math.atan2(dir.x, dir.z);
    for (const [s0, s1] of spans) {
      if (s1 - s0 < 0.02) continue;
      const box = new THREE.Mesh(new THREE.BoxGeometry(t, WALL_H, s1 - s0 + t * 0.5), wm);
      const mid = a.clone().addScaledVector(dir, (s0 + s1) / 2);
      box.position.set(mid.x, WALL_H / 2, mid.z);
      box.rotation.y = angle;
      box.castShadow = true; box.receiveShadow = true;
      box.scale.y = 0.001; box.visible = false;
      group.add(box);
      out.push(box);
    }
    for (const [s0, s1, k] of cuts) {
      if (k.includes("door")) continue;
      const pane = new THREE.Mesh(new THREE.BoxGeometry(0.03, WALL_H * 0.55, s1 - s0),
        new THREE.MeshStandardMaterial({ color: COL.glass, transparent: true, opacity: 0.45, roughness: 0.1 }));
      const mid = a.clone().addScaledVector(dir, (s0 + s1) / 2);
      pane.position.set(mid.x, WALL_H * 0.55, mid.z);
      pane.rotation.y = angle;
      pane.scale.y = 0.001; pane.visible = false;
      group.add(pane);
      out.push(pane);
    }
    return out;
  }

  // Draw a scheme: the planning sketch steps aside, each member takes
  // their zone, and the outlines are walked out one by one.
  draw(id, { fast = false } = {}) {
    const s = this.schemes[id];
    if (!s) return Promise.resolve();
    this.planningActive = false;
    for (const other of Object.values(this.schemes)) {
      if (other !== s && other.group.visible) {
        other.group.visible = false;
        other.rooms.forEach((r) => this._show(r.lab, false));
      }
    }
    this.planning.children.forEach((c) => c.material && this._fade(c.material, c.material.opacity * 0.25, 700));
    this.labels.filter((l) => l.el.classList.contains("st-label--zone")).forEach((l) => this._show(l, false));
    s.group.visible = true;
    this.current = s;

    if (s.drawn) return Promise.resolve();
    if (this.static) {
      s.rooms.forEach((r) => this._complete(r, true));
      this._rise(s, true);
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      s.resolve = resolve;
      const queues = { public: [], service: [], private: [] };
      // Front to back on each plate, plate by plate.
      [...s.rooms].sort((a, b) => a.li - b.li || a.centre.z - b.centre.z).forEach((r) => queues[r.zone].push(r));
      const owner = { public: "arch1", service: "eng", private: "arch2" };
      const hands = Object.entries(queues).map(([z, q]) => ({ who: this._member(owner[z]), q }));
      for (const h of hands) {
        if (!h.q.length) {
          const busiest = hands.reduce((a, b) => (b.q.length > a.q.length ? b : a));
          if (busiest.q.length > 1) h.q.push(...busiest.q.splice(Math.ceil(busiest.q.length / 2)));
        }
      }
      for (const h of hands) {
        h.who.tasks = [];
        h.who.task = null;
        for (const r of h.q) {
          const pts = resample(r.pts, 0.08, true);
          h.who.tasks.push({ type: "run", to: pts[0] }, { type: "draw", pts, line: r.line, room: r, fast });
        }
      }
      s.pending = s.rooms.length;
    });
  }

  _complete(r, instant = false) {
    if (r.drawn) return;
    r.drawn = true;
    r.line.geometry.setDrawRange(0, r.line.userData.count);
    if (instant) r.fill.material.opacity = 0.16;
    else this._fade(r.fill.material, 0.16, 500);
    this._show(r.lab);
    const s = this.current;
    if (s && s.rooms.includes(r) && s.rooms.every((x) => x.drawn) && !s.drawn) {
      s.drawn = true;
      this._rise(s, instant);
    }
  }

  // The walls go up in a wave from the road, then the team steps back.
  _rise(s, instant = false) {
    if (s.risen) return;
    s.risen = true;
    const front = this.P(0, this.plot.w / 2, this.plot.road === "S" ? 0 : this.plot.d);
    const order = s.walls.map((m) => ({ m, k: m.position.distanceTo(front) })).sort((a, b) => a.k - b.k);
    const span = order.length ? order[order.length - 1].k || 1 : 1;
    for (const { m, k } of order) {
      m.visible = true;
      if (instant) { m.scale.y = 1; continue; }
      setTimeout(() => this._tween(520, (t) => { m.scale.y = Math.max(0.001, ease(t)); }), (k / span) * 900 / this.speed);
    }
    const done = () => {
      this._standBack();
      s.resolve?.();
    };
    if (instant) done(); else setTimeout(done, 1100 / this.speed);
  }

  _standBack() {
    const { w, d, n } = this.plot;
    const spots = [this.P(0, -1.6, d * 0.35), this.P(0, -1.6, d * 0.7), this.P(n - 1, w + 1.6, d * 0.5)];
    this.team.forEach((t, i) => { t.tasks = [{ type: "run", to: spots[i] }, { type: "face", to: this.view.target }]; t.task = null; });
  }

  // A specialist's remark names a room: light it, and send someone over.
  highlight(text) {
    const s = this.current;
    if (!s || !s.drawn || !text) return;
    const t = text.toLowerCase();
    const r = [...s.rooms].sort((a, b) => b.room.name.length - a.room.name.length)
      .find((x) => t.includes(x.room.name.toLowerCase()));
    if (!r) return;
    const base = 0.16;
    this._tween(1400, (k) => { r.fill.material.opacity = base + Math.sin(k * Math.PI) * 0.22; });
    r.lab.el.classList.add("is-hot");
    setTimeout(() => r.lab.el.classList.remove("is-hot"), 1600);
    if (this.static) return;
    const idle = this.team.filter((m) => !m.task && !m.tasks.length);
    const who = idle.sort((a, b) => a.fig.position.distanceTo(r.centre) - b.fig.position.distanceTo(r.centre))[0];
    if (who) {
      const near = r.centre.clone().add(new THREE.Vector3(0.6, 0, 0.6));
      who.tasks.push({ type: "run", to: near }, { type: "face", to: r.centre }, { type: "point", t: 1.2 });
    }
  }

  // Hurry, settle to plan view, and resolve when the board is still.
  async settle() {
    this.speed = 6;
    const s = this.current;
    if (s && !s.drawn) {
      await new Promise((r) => setTimeout(r, 700));
      s.rooms.forEach((x) => this._complete(x, true));
    }
    if (s) this._rise(s, true);
    await new Promise((resolve) => {
      if (this.static) { this.view.tilt = 0; resolve(); return; }
      const from = this.view.tilt;
      this._tween(900, (k) => { this.view.tilt = lerp(from, 0, ease(k)); }, resolve);
    });
  }

  /* ── animation plumbing ──────────────────────────────────────────── */

  _fade(material, to, ms) {
    const from = material.opacity;
    this._tween(ms, (k) => { material.opacity = lerp(from, to, ease(k)); });
  }

  _tween(ms, fn, done) {
    (this.tweens ||= []).push({ t: 0, ms: Math.max(1, ms), fn, done });
  }

  _tick(now) {
    this.raf = requestAnimationFrame(this._tick);
    const dt = Math.min(0.05, (now - (this.last || now)) / 1000);
    this.last = now;
    const step = dt * this.speed;

    if (this.tweens?.length) {
      for (const tw of this.tweens) {
        tw.t += dt * 1000 * Math.max(1, this.speed * 0.6);
        tw.fn(clamp(tw.t / tw.ms, 0, 1));
      }
      const done = this.tweens.filter((tw) => tw.t >= tw.ms);
      this.tweens = this.tweens.filter((tw) => tw.t < tw.ms);
      done.forEach((tw) => tw.done?.());
    }

    if (!this.static) for (const m of this.team) this._member_tick(m, step, now);

    this._placeCamera(now);
    this.renderer.render(this.scene, this.camera);
    this._labelsTick();
  }

  _member_tick(m, step, now) {
    const fig = m.fig;
    const u = fig.userData;
    if (!m.task) {
      m.task = m.tasks.shift() || null;
      if (!m.task && this.planningActive && this.construction.length) {
        // Keep working: take the next grid line.
        const [a, b] = this.construction.shift();
        m.tasks.push({ type: "run", to: a }, { type: "draw", pts: resample([a, b]), line: this._line([a, b], COL.chalk, 0.22, this.planning) });
        m.task = m.tasks.shift();
      }
      if (!m.task && this.planningActive && now > m.busyUntil) {
        // Pace the plot, looking it over.
        const { w, d, n } = this.plot;
        const to = this.P(Math.floor(Math.random() * n), 0.8 + Math.random() * (w - 1.6), 0.8 + Math.random() * (d - 1.6));
        m.tasks.push({ type: "run", to, slow: true }, { type: "wait", t: 0.8 + Math.random() * 1.2 });
        m.busyUntil = now + 2000;
      }
    }

    let moving = false, drawing = false, pointing = false;
    const t = m.task;
    if (t) {
      if (t.type === "run") {
        const v = t.to.clone().sub(fig.position);
        v.y = 0;
        const dist = v.length();
        const sp = (t.slow ? RUN * 0.45 : RUN) * step;
        if (dist <= sp || dist < 0.02) { fig.position.set(t.to.x, 0, t.to.z); m.task = null; }
        else { fig.position.addScaledVector(v.normalize(), sp); m.face = Math.atan2(v.x, v.z); moving = true; }
      } else if (t.type === "draw") {
        t.i = (t.i ?? 0);
        const pace = (t.fast ? PACE * 3 : PACE) * step;
        t.acc = (t.acc ?? 0) + pace / 0.08;
        const before = t.i;
        while (t.acc >= 1 && t.i < t.pts.length - 1) { t.i++; t.acc -= 1; }
        const p = t.pts[t.i];
        if (t.i > before) {
          const q = t.pts[Math.max(0, t.i - 1)];
          m.face = Math.atan2(p.x - q.x, p.z - q.z);
        }
        fig.position.set(p.x, 0, p.z);
        t.line.geometry.setDrawRange(0, t.i + 1);
        drawing = true;
        if (t.i >= t.pts.length - 1) {
          if (t.room) this._complete(t.room);
          m.task = null;
        }
      } else if (t.type === "wait") {
        t.left = (t.left ?? t.t) - step;
        if (t.left <= 0) m.task = null;
      } else if (t.type === "point") {
        t.left = (t.left ?? t.t) - step;
        pointing = true;
        if (t.left <= 0) m.task = null;
      } else if (t.type === "face") {
        const v = t.to.clone().sub(fig.position);
        m.face = Math.atan2(v.x, v.z);
        m.task = null;
      } else if (t.type === "call") {
        t.fn();
        m.task = null;
      }
    }

    // Turn toward travel, smoothly.
    let dy = m.face - fig.rotation.y;
    dy = Math.atan2(Math.sin(dy), Math.cos(dy));
    fig.rotation.y += dy * Math.min(1, step * 12);

    // Gait: run, walk-and-draw, or stand.
    const freq = moving ? 11 : drawing ? 7 : 1.6;
    u.phase += step * freq;
    const swing = moving ? 0.85 : drawing ? 0.45 : 0;
    u.legL.rotation.x = Math.sin(u.phase) * swing;
    u.legR.rotation.x = -Math.sin(u.phase) * swing;
    u.armL.rotation.x = -Math.sin(u.phase) * swing * 0.8;
    u.body.position.y = moving ? Math.abs(Math.sin(u.phase)) * 0.045 : Math.sin(u.phase) * 0.004;
    u.body.rotation.x = moving ? 0.16 : drawing ? 0.28 : 0;
    // The working arm: down to the ground while drawing, up while pointing.
    const armTarget = drawing ? -0.95 : pointing ? -2.4 : moving ? Math.sin(u.phase) * swing * 0.8 : -0.1;
    u.armR.rotation.x += (armTarget - u.armR.rotation.x) * Math.min(1, step * 14);
  }

  _labelsTick() {
    if (!this.labels.length) return;
    const w = this.host.clientWidth, h = this.host.clientHeight;
    const v = new THREE.Vector3();
    for (const l of this.labels) {
      if (!l.on) continue;
      v.copy(l.world).project(this.camera);
      const x = (v.x * 0.5 + 0.5) * w, y = (-v.y * 0.5 + 0.5) * h;
      l.el.style.transform = `translate3d(${x.toFixed(1)}px, ${y.toFixed(1)}px, 0) translate(-50%, -50%)`;
    }
  }

  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    this.renderer.dispose();
    this.host.innerHTML = "";
  }
}

