.atelier {
  height: 100%;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
}

.at-main {
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
}

/* the stage: the model fills it, the caption sits on top */
.at-stage {
  position: relative;
  min-height: 0;
  overflow: hidden;
  background:
    radial-gradient(120% 90% at 50% 40%, #0F1116 0%, #0B0C10 55%, #08090C 100%);
  view-transition-name: sheet;
}
.at-3d { position: absolute; inset: 0; }
.st-canvas { display: block; width: 100%; height: 100%; }
.st-labels { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.st-label {
  position: absolute; left: 0; top: 0;
  padding: 2px 6px; border-radius: 4px;
  font-size: 10.5px; font-weight: 500; letter-spacing: 0.01em; white-space: nowrap;
  color: rgba(236, 239, 244, 0.86);
  background: rgba(8, 9, 12, 0.62);
  opacity: 0; transition: opacity 0.4s var(--ease-out), color 0.3s, background-color 0.3s;
}
.st-label.is-on { opacity: 1; }
.st-label--zone {
  font-size: 10px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--gold); background: transparent;
}
.st-label.is-hot { color: var(--ink-dark); background: var(--gold); }

.at-cap {
  position: absolute; left: 28px; top: 24px; z-index: 2;
  max-width: min(520px, 70%);
  pointer-events: none;
}
.at-eyebrow {
  margin: 0 0 6px;
  font-size: 10.5px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--gold);
}
.at-cap h2 { margin: 0; font-size: 20px; font-weight: 600; letter-spacing: -0.01em; color: var(--chalk); }
.at-sub { margin: 4px 0 0; font-family: var(--num); font-size: 12px; color: var(--chalk-3); white-space: pre; }

.at-note {
  position: absolute; left: 28px; bottom: 24px; z-index: 2; max-width: 460px;
  margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--chalk-3);
}
.at-fail {
  position: absolute; inset: 0; z-index: 3;
  display: grid; place-content: center; justify-items: start; gap: 10px;
  padding: 24px; max-width: 520px; margin: 0 auto;
}
.at-fail h3 { margin: 0; font-size: 18px; font-weight: 600; color: var(--chalk); }
.at-fail p { margin: 0 0 6px; font-size: 13px; line-height: 1.55; color: var(--chalk-2); }
.at-stage:has(.at-fail:not([hidden])) .at-3d { opacity: 0.25; filter: grayscale(1); transition: opacity 0.4s; }

/* the column: scores, filled in as each specialist reports */
.at-side {
  min-height: 0;
  display: flex; flex-direction: column;
  border-left: 1px solid var(--rule);
  background: #08090C;
}
.at-side__h {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 20px 20px 0;
}
.at-side__h h3 {
  margin: 0; font-size: 10.5px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--chalk-3);
}
.at-pills { display: flex; gap: 4px; }
.pill {
  display: inline-flex; align-items: baseline; gap: 6px;
  height: 26px; padding: 0 9px; border: 0; border-radius: 6px;
  font: inherit; font-size: 12px; color: var(--chalk-3);
  background: transparent; box-shadow: inset 0 0 0 1px var(--rule);
  cursor: pointer; transition: color 0.2s, background-color 0.2s, box-shadow 0.2s;
}
.pill span { font-weight: 600; line-height: 26px; }
.pill b { font-family: var(--num); font-size: 11px; font-weight: 500; font-variant-numeric: tabular-nums; }
.pill b:empty { display: none; }
.pill:hover { color: var(--chalk); }
.pill[aria-selected="true"] { color: var(--chalk); background: #13151A; box-shadow: inset 0 0 0 1px var(--rule-2); }
.pill[data-state="chosen"] { color: var(--gold); box-shadow: inset 0 0 0 1px var(--gold); }
.pill:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

.at-overall {
  display: flex; align-items: baseline; justify-content: space-between;
  margin: 18px 20px 0; padding-bottom: 14px; border-bottom: 1px solid var(--rule);
}
.at-overall span { font-size: 12px; color: var(--chalk-3); }
.at-overall b {
  font-family: var(--num); font-size: 30px; font-weight: 600; line-height: 1;
  font-variant-numeric: tabular-nums; color: var(--chalk);
}
.at-main[data-done="1"] .at-overall b { color: var(--gold); }

.at-voice {
  min-height: 62px; margin: 0; padding: 12px 20px;
  font-size: 12.5px; line-height: 1.5; color: var(--chalk-2);
  border-bottom: 1px solid var(--rule);
  display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden;
}
.at-voice b { display: block; margin-bottom: 2px; font-size: 11px; font-weight: 600; color: var(--gold); }
.at-voice:empty::before { content: "Scores appear as each specialist reports."; color: var(--chalk-4); }

.at-scores {
  flex: 1 1 auto; min-height: 0; overflow-y: auto;
  margin: 0; padding: 6px 0 12px; list-style: none;
  scrollbar-width: thin; scrollbar-color: var(--rule-2) transparent;
}
.sc {
  position: relative;
  display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; align-items: center; gap: 0 10px;
  padding: 7px 20px 9px;
  transition: background-color 0.3s;
}
.sc .av { opacity: 0.55; transition: opacity 0.3s; }
.sc__n { font-size: 12.5px; color: var(--chalk-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color 0.3s; }
.sc__v { font-family: var(--num); font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--chalk-4); }
.sc__b {
  grid-column: 2 / -1; display: block; height: 2px; margin-top: 6px;
  border-radius: 2px; background: var(--rule); overflow: hidden;
}
.sc__b b {
  display: block; height: 100%; border-radius: inherit;
  background: var(--chalk-3); transform: scaleX(0); transform-origin: left;
  transition: transform 0.6s var(--ease-out), background-color 0.3s;
}
.sc[data-state="reading"] .sc__b {
  background: linear-gradient(90deg, var(--rule) 0 30%, rgba(236, 239, 244, 0.16) 50%, var(--rule) 70% 100%) 0 0 / 300% 100%;
  animation: at-scan 1.6s linear infinite;
}
.sc[data-state="done"] .av, .sc[data-state="low"] .av { opacity: 1; }
.sc[data-state="done"] .sc__n, .sc[data-state="low"] .sc__n { color: var(--chalk-2); }
.sc[data-state="done"] .sc__v { color: var(--chalk); }
.sc[data-state="low"] .sc__v { color: var(--hingula); }
.sc[data-state="low"] .sc__b b { background: var(--hingula); }
.sc.is-speaking { background: rgba(229, 169, 88, 0.06); }
.sc.is-speaking::before { content: ""; position: absolute; left: 0; top: 8px; bottom: 8px; width: 2px; background: var(--gold); }
.sc.is-speaking .sc__b b { background: var(--gold); }
@keyframes at-scan { from { background-position: 100% 0; } to { background-position: -50% 0; } }

/* the footer: one status line, a bar that keeps moving */
.at-foot { border-top: 1px solid var(--rule); background: #08090C; }
.at-foot__row {
  display: flex; align-items: center; gap: 14px;
  min-height: 52px; padding: 0 20px 0 28px;
}
.at-step { flex: 0 0 auto; font-size: 13px; font-weight: 600; color: var(--chalk); }
.at-msg {
  flex: 1 1 auto; min-width: 0;
  font-size: 12.5px; color: var(--chalk-3);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.at-clock { flex: 0 0 auto; font-family: var(--num); font-size: 12px; font-variant-numeric: tabular-nums; color: var(--chalk-4); }
.at-btn {
  flex: 0 0 auto; height: 30px; padding: 0 12px; border: 0; border-radius: 6px;
  font: inherit; font-size: 12.5px; font-weight: 500; color: var(--chalk-2);
  background: transparent; box-shadow: inset 0 0 0 1px var(--rule-2);
  cursor: pointer; transition: color 0.2s, background-color 0.2s;
}
.at-btn:hover { color: var(--chalk); background: rgba(255, 255, 255, 0.04); }
.at-btn--go { color: var(--ink-dark); background: var(--gold); box-shadow: none; font-weight: 600; }
.at-btn--go:hover { color: var(--ink-dark); background: var(--gold-hi); }
.at-btn:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
#at-open:not([hidden]) { animation: at-rise 0.35s var(--ease-out) both; }
@keyframes at-rise { from { opacity: 0; transform: translateY(6px); } }

.at-track { position: relative; height: 2px; background: rgba(255, 255, 255, 0.05); overflow: hidden; }
.at-track i {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(229, 169, 88, 0.55), var(--gold));
  transform: scaleX(0); transform-origin: left;
}
.at-track i::after {
  content: ""; position: absolute; right: 0; top: 0; bottom: 0; width: 120px;
  background: linear-gradient(90deg, transparent, rgba(255, 236, 200, 0.9));
  animation: at-glint 1.8s ease-in-out infinite;
}
.at-main[data-done="1"] ~ .at-foot .at-track i::after { animation: none; opacity: 0; }
@keyframes at-glint { 0%, 100% { opacity: 0.25; } 50% { opacity: 1; } }

/* ── the review: the team keeps what it said ────────────────────────── */

/* ── smaller screens ────────────────────────────────────────────────── */

@media (max-width: 1100px) {
  .at-main { grid-template-columns: minmax(0, 1fr) 260px; }
}

@media (max-width: 820px) {
  .running { overflow-y: auto; }
  .atelier { height: auto; min-height: 100%; grid-template-rows: auto auto; }
  .at-main { grid-template-columns: minmax(0, 1fr); }
  .at-stage { height: 56vh; min-height: 320px; }
  .at-side { border-left: 0; border-top: 1px solid var(--rule); }
  .at-scores { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); overflow: visible; }
  .at-foot { position: sticky; bottom: 0; }
}

@media (max-width: 560px) {
  .at-cap { left: 16px; top: 16px; max-width: calc(100% - 32px); }
  .at-cap h2 { font-size: 17px; }
  .at-sub { white-space: normal; }
  .at-side__h, .sc, .at-voice { padding-left: 16px; padding-right: 16px; }
  .at-overall { margin-left: 16px; margin-right: 16px; }
  .at-scores { grid-template-columns: minmax(0, 1fr); }
  .at-foot__row { padding: 0 16px; gap: 10px; }
  .at-msg { display: none; }
  .at-step { flex: 1 1 auto; }
}

@media (prefers-reduced-motion: reduce) {
  .sc[data-state="reading"] .sc__b, .at-track i::after,
  #at-open:not([hidden]), .tm__more:not([hidden]) { animation: none; }
}

