30	};
31	
32	const PUBLIC = new Set(["foyer", "living", "dining", "puja", "verandah", "garage", "drawing", "family", "lobby", "home_office"]);
33	const PRIVATE = new Set(["master_bedroom", "bedroom", "guest_bedroom", "children_bedroom", "study", "balcony", "terrace", "wardrobe", "servant"]);
34	const WET = new Set(["bathroom", "toilet", "powder", "utility", "laundry"]);
35	const zoneOf = (t) => (PUBLIC.has(t) ? "public" : PRIVATE.has(t) ? "private" : "service");
