47	// Points along a polyline every `step` metres, so a line can be revealed
48	// at the pace someone walks it.
49	function resample(pts, step = 0.08, closed = false) {
50	  const src = closed ? [...pts, pts[0]] : pts;
51	  const out = [src[0].clone()];
52	  for (let i = 1; i < src.length; i++) {
53	    const a = src[i - 1], b = src[i];
54	    const n = Math.max(1, Math.ceil(a.distanceTo(b) / step));
55	    for (let k = 1; k <= n; k++) out.push(a.clone().lerp(b, k / n));
56	  }
57	  return out;
58	}
