60	function lineOf(points, color, opacity = 1, y = 0.02) {
61	  const pos = new Float32Array(points.length * 3);
62	  points.forEach((p, i) => { pos[i * 3] = p.x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = p.z; });
63	  const g = new THREE.BufferGeometry();
64	  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
65	  g.setDrawRange(0, 0);
66	  const m = new THREE.LineBasicMaterial({ color, transparent: true, opacity });
67	  const line = new THREE.Line(g, m);
68	  line.userData.count = points.length;
69	  return line;
70	}
