123	  const armR = limb(0.04, 0.26, L.shirt); armR.position.set(0.17, 0.82, 0);
124	  body.add(legL, legR, torso, head, armL, armR);
125	
126	  if (L.hat) {
127	    const dome = new THREE.Mesh(new THREE.SphereGeometry(0.118, 16, 8, 0, TAU, 0, Math.PI / 2), mat(L.hat, 0.45));
128	    dome.position.y = 1.0;
129	    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 0.014, 20), mat(L.hat, 0.45));
130	    brim.position.y = 1.0;
131	    body.add(dome, brim);
132	  } else {
