141	    const p = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.2, 6), mat(COL.gold, 0.4));
142	    p.position.y = -0.1;
143	    tool.add(p);
144	  } else {
145	    const s = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.95, 6), mat(0xf2b33d, 0.5));
