336	  /* ── labels ───────────────────────────────────────────────────────── */
337	
338	  _label(text, world, cls = "") {
339	    const el = document.createElement("span");
340	    el.className = `st-label ${cls}`;
341	    el.textContent = text;
342	    this.labelLayer.append(el);
343	    const l = { el, world: world.clone(), on: false };
344	    this.labels.push(l);
345	    return l;
346	  }
347	
348	  _show(l, on = true) {
349	    l.on = on;
350	    l.el.classList.toggle("is-on", on);
351	  }
352	
353	  /* ── tasks ────────────────────────────────────────────────────────── */
354	
355	  _do(who, ...tasks) { who.tasks.push(...tasks); }
356	  _member(kind) { return this.team.find((t) => t.kind === kind); }
357	
358	  // The first minutes on site: stake it out, chalk the setbacks, zone it.
359	  plan(brief) {
360	    const { w, d, n } = this.plot;
361	    const eng = this._member("eng"), a1 = this._member("arch1"), a2 = this._member("arch2");
362	    this.team.forEach((t, i) => { t.fig.position.copy(this.P(0, -6 - i * 1.2, d * 0.3 + i)); t.tasks = []; t.task = null; });
363	
364	    for (let i = 0; i < n; i++) {
365	      // Corner stakes, and the boundary walked between them.
366	      const corners = [[0, 0], [w, 0], [w, d], [0, d]].map(([x, y]) => this.P(i, x, y));
367	      this._do(eng, { type: "run", to: corners[0] });
368	      corners.forEach((c, k) => {
369	        this._do(eng, { type: "call", fn: () => this._stake(c) });
370	        const next = corners[(k + 1) % 4];
371	        this._do(eng, { type: "draw", pts: resample([c, next]), line: this._line([c, next], COL.line, i === 0 ? 0.55 : 0.28) });
372	      });
373	    }
374	
375	    // Setbacks, chalked in gold on the ground plate.
376	    const sb = this.setbacks;
377	    if (sb) {
378	      const r = this.plot.road;
379	      const inset = r === "N" ? { t: sb.front, b: sb.rear, l: sb.left, r: sb.right }
380	        : r === "S" ? { t: sb.rear, b: sb.front, l: sb.right, r: sb.left }
381	          : r === "E" ? { t: sb.left, b: sb.right, l: sb.rear, r: sb.front }
382	            : { t: sb.right, b: sb.left, l: sb.front, r: sb.rear };
383	      const pts = [[inset.l, inset.b], [w - inset.r, inset.b], [w - inset.r, d - inset.t], [inset.l, d - inset.t], [inset.l, inset.b]]
384	        .map(([x, y]) => this.P(0, x, y));
385	      this._do(a1, { type: "wait", t: 0.6 }, { type: "run", to: pts[0] });
386	      for (let k = 1; k < pts.length; k++) {
387	        this._do(a1, { type: "draw", pts: resample([pts[k - 1], pts[k]]), line: this._line([pts[k - 1], pts[k]], COL.gold, 0.5) });
388	      }
389	    }
390	
391	    // Zoning: living to the road, services behind, bedrooms to the back
392	    // (or upstairs) - the arrangement the generator itself starts from.
393	    const zones = n > 1
394	      ? [[0, "Living & arrival", 0.0, 0.45, COL.public], [0, "Kitchen & services", 0.45, 1.0, COL.service], [1, "Bedrooms", 0.0, 1.0, COL.private]]
395	      : [[0, "Living & arrival", 0.0, 0.36, COL.public], [0, "Kitchen & services", 0.36, 0.6, COL.service], [0, "Bedrooms", 0.6, 1.0, COL.private]];
396	    this._do(a2, { type: "wait", t: 1.2 });
397	    for (const [lv, name, f0, f1, color] of zones) {
398	      const m = 1.0;
399	      const y0 = this._depth(f1), y1 = this._depth(f0);
400	      const lo = Math.min(y0, y1) + m * 0.5, hi = Math.max(y0, y1) - m * 0.5;
401	      const rect = [[m, lo], [w - m, lo], [w - m, hi], [m, hi], [m, lo]].map(([x, y]) => this.P(lv, x, y));
402	      this._do(a2, { type: "run", to: rect[0] });
403	      const fill = shapeFill(rect.slice(0, 4), color, 0);
404	      this.planning.add(fill);
405	      for (let k = 1; k < rect.length; k++) {
406	        this._do(a2, { type: "draw", pts: resample([rect[k - 1], rect[k]]), line: this._line([rect[k - 1], rect[k]], color, 0.6, this.planning) });
407	      }
408	      const centre = rect.slice(0, 4).reduce((a, p) => a.add(p), new THREE.Vector3()).multiplyScalar(0.25);
409	      const lab = this._label(name, centre, "st-label--zone");
410	      this._do(a2, { type: "call", fn: () => { this._fade(fill.material, 0.07, 500); this._show(lab); } });
411	    }
412	
413	    // Then the column grid, line by line, until the schemes arrive.
414	    for (let i = 0; i < n; i++) {
415	      for (let x = 3.8; x < w - 0.5; x += 3.8) this.construction.push([this.P(i, x, 0.3), this.P(i, x, d - 0.3)]);
416	      for (let y = 3.8; y < d - 0.5; y += 3.8) this.construction.push([this.P(i, 0.3, y), this.P(i, w - 0.3, y)]);
417	    }
418	    this.planningActive = true;
419	  }
420	
421	  // Fraction of depth from the road (0) to the rear (1), as a plan y.
422	  _depth(f) {
423	    const { d, road } = this.plot;
424	    return road === "S" ? f * d : d - f * d;
425	  }
426	
427	  _line(pts, color, opacity, parent = this.root) {
428	    const line = lineOf(resample(pts), color, opacity);
429	    parent.add(line);
430	    return line;
431	  }
432	
433	  _stake(at) {
434	    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.5, 8), mat(0xe9ecf1));
435	    post.position.set(at.x, 0.25, at.z);
436	    post.castShadow = true;
437	    const cap = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.12, 10), mat(0xe8792f, 0.5));
438	    cap.position.set(at.x, 0.56, at.z);
439	    const g = new THREE.Group();
440	    g.add(post, cap);
441	    g.scale.setScalar(0.01);
442	    this.root.add(g);
443	    this._tween(400, (k) => g.scale.setScalar(Math.max(0.01, ease(k))));
444	  }
445	
446	  /* ── the schemes ──────────────────────────────────────────────────── */
447	
448	  // Build a scheme's geometry (hidden) so it can be drawn on demand.
449	  addScheme(sk) {
450	    if (this.schemes[sk.id]) return this.schemes[sk.id];
451	    const group = new THREE.Group();
452	    group.visible = false;
453	    this.root.add(group);
454	    const rooms = [];
455	    const walls = [];
456	    sk.levels.forEach((lv, li) => {
457	      if (li >= this.plot.n) return;
458	      for (const room of lv.rooms) {
459	        const pts = room.poly.map((p) => this.P(li, p[0], p[1]));
460	        const line = lineOf(resample(pts, 0.08, true), COL.line, 0.9, 0.03);
461	        const fill = shapeFill(pts, COL[tintOf(room.type)], 0);
462	        group.add(fill, line);
463	        const c = pts.reduce((a, p) => a.add(p), new THREE.Vector3()).multiplyScalar(1 / pts.length);
464	        const lab = this._label(`${room.name}`, c, "st-label--room");
465	        lab.scheme = sk.id;
466	        rooms.push({ room, li, pts, line, fill, lab, centre: c, zone: zoneOf(room.type), drawn: false });
467	      }
468	      for (const w of lv.walls) walls.push(...this._wallPieces(group, li, w));
469	    });
470	    const s = { sk, group, rooms, walls, drawn: false, risen: false };
471	    this.schemes[sk.id] = s;
472	    return s;
473	  }
474	
475	  // A wall as boxes between its openings; glazing as a pane in the gap.
476	  _wallPieces(group, li, w) {
477	    const a = this.P(li, w.a[0], w.a[1]), b = this.P(li, w.b[0], w.b[1]);
478	    const len = a.distanceTo(b);
479	    if (len < 0.05) return [];
480	    const dir = b.clone().sub(a).normalize();
481	    const cuts = w.open.map((o) => [clamp(o.p * len - o.w / 2, 0, len), clamp(o.p * len + o.w / 2, 0, len), o.k])
482	      .sort((x, y) => x[0] - y[0]);
483	    const spans = [];
484	    let at = 0;
485	    for (const [s0, s1] of cuts) { if (s0 > at) spans.push([at, s0]); at = Math.max(at, s1); }
486	    if (at < len) spans.push([at, len]);
487	    const t = Math.max(0.1, w.t);
488	    const wm = mat(w.ext ? COL.wall : 0xd6dae2, 0.85);
489	    const out = [];
490	    const angle = Math.atan2(dir.x, dir.z);
491	    for (const [s0, s1] of spans) {
492	      if (s1 - s0 < 0.02) continue;
493	      const box = new THREE.Mesh(new THREE.BoxGeometry(t, WALL_H, s1 - s0 + t * 0.5), wm);
494	      const mid = a.clone().addScaledVector(dir, (s0 + s1) / 2);
495	      box.position.set(mid.x, WALL_H / 2, mid.z);
496	      box.rotation.y = angle;
497	      box.castShadow = true; box.receiveShadow = true;
498	      box.scale.y = 0.001; box.visible = false;
499	      group.add(box);
500	      out.push(box);
501	    }
502	    for (const [s0, s1, k] of cuts) {
503	      if (k.includes("door")) continue;
504	      const pane = new THREE.Mesh(new THREE.BoxGeometry(0.03, WALL_H * 0.55, s1 - s0),
505	        new THREE.MeshStandardMaterial({ color: COL.glass, transparent: true, opacity: 0.45, roughness: 0.1 }));
506	      const mid = a.clone().addScaledVector(dir, (s0 + s1) / 2);
507	      pane.position.set(mid.x, WALL_H * 0.55, mid.z);
508	      pane.rotation.y = angle;
509	      pane.scale.y = 0.001; pane.visible = false;
510	      group.add(pane);
511	      out.push(pane);
512	    }
513	    return out;
514	  }
515	
516	  // Draw a scheme: the planning sketch steps aside, each member takes
517	  // their zone, and the outlines are walked out one by one.
518	  draw(id, { fast = false } = {}) {
519	    const s = this.schemes[id];
520	    if (!s) return Promise.resolve();
521	    this.planningActive = false;
522	    for (const other of Object.values(this.schemes)) {
523	      if (other !== s && other.group.visible) {
524	        other.group.visible = false;
525	        other.rooms.forEach((r) => this._show(r.lab, false));
526	      }
527	    }
528	    this.planning.children.forEach((c) => c.material && this._fade(c.material, c.material.opacity * 0.25, 700));
529	    this.labels.filter((l) => l.el.classList.contains("st-label--zone")).forEach((l) => this._show(l, false));
530	    s.group.visible = true;
531	    this.current = s;
532	
533	    if (s.drawn) return Promise.resolve();
534	    if (this.static) {
535	      s.rooms.forEach((r) => this._complete(r, true));
536	      this._rise(s, true);
537	      return Promise.resolve();
538	    }
539	    return new Promise((resolve) => {
540	      s.resolve = resolve;
541	      const queues = { public: [], service: [], private: [] };
542	      // Front to back on each plate, plate by plate.
543	      [...s.rooms].sort((a, b) => a.li - b.li || a.centre.z - b.centre.z).forEach((r) => queues[r.zone].push(r));
544	      const owner = { public: "arch1", service: "eng", private: "arch2" };
545	      const hands = Object.entries(queues).map(([z, q]) => ({ who: this._member(owner[z]), q }));
546	      for (const h of hands) {
547	        if (!h.q.length) {
548	          const busiest = hands.reduce((a, b) => (b.q.length > a.q.length ? b : a));
549	          if (busiest.q.length > 1) h.q.push(...busiest.q.splice(Math.ceil(busiest.q.length / 2)));
550	        }
551	      }
552	      for (const h of hands) {
553	        h.who.tasks = [];
554	        h.who.task = null;
555	        for (const r of h.q) {
556	          const pts = resample(r.pts, 0.08, true);
557	          h.who.tasks.push({ type: "run", to: pts[0] }, { type: "draw", pts, line: r.line, room: r, fast });
558	        }
559	      }
560	      s.pending = s.rooms.length;
561	    });
562	  }
563	
564	  _complete(r, instant = false) {
565	    if (r.drawn) return;
566	    r.drawn = true;
567	    r.line.geometry.setDrawRange(0, r.line.userData.count);
568	    if (instant) r.fill.material.opacity = 0.16;
569	    else this._fade(r.fill.material, 0.16, 500);
570	    this._show(r.lab);
571	    const s = this.current;
572	    if (s && s.rooms.includes(r) && s.rooms.every((x) => x.drawn) && !s.drawn) {
573	      s.drawn = true;
574	      this._rise(s, instant);
575	    }
576	  }
577	
578	  // The walls go up in a wave from the road, then the team steps back.
579	  _rise(s, instant = false) {
580	    if (s.risen) return;
581	    s.risen = true;
582	    const front = this.P(0, this.plot.w / 2, this.plot.road === "S" ? 0 : this.plot.d);
583	    const order = s.walls.map((m) => ({ m, k: m.position.distanceTo(front) })).sort((a, b) => a.k - b.k);
584	    const span = order.length ? order[order.length - 1].k || 1 : 1;
585	    for (const { m, k } of order) {
586	      m.visible = true;
587	      if (instant) { m.scale.y = 1; continue; }
588	      setTimeout(() => this._tween(520, (t) => { m.scale.y = Math.max(0.001, ease(t)); }), (k / span) * 900 / this.speed);
589	    }
590	    const done = () => {
591	      this._standBack();
592	      s.resolve?.();
593	    };
594	    if (instant) done(); else setTimeout(done, 1100 / this.speed);
595	  }
596	
597	  _standBack() {
598	    const { w, d, n } = this.plot;
599	    const spots = [this.P(0, -1.6, d * 0.35), this.P(0, -1.6, d * 0.7), this.P(n - 1, w + 1.6, d * 0.5)];
600	    this.team.forEach((t, i) => { t.tasks = [{ type: "run", to: spots[i] }, { type: "face", to: this.view.target }]; t.task = null; });
601	  }
602	
603	  // A specialist's remark names a room: light it, and send someone over.
604	  highlight(text) {
605	    const s = this.current;
606	    if (!s || !s.drawn || !text) return;
607	    const t = text.toLowerCase();
608	    const r = [...s.rooms].sort((a, b) => b.room.name.length - a.room.name.length)
609	      .find((x) => t.includes(x.room.name.toLowerCase()));
610	    if (!r) return;
611	    const base = 0.16;
612	    this._tween(1400, (k) => { r.fill.material.opacity = base + Math.sin(k * Math.PI) * 0.22; });
613	    r.lab.el.classList.add("is-hot");
614	    setTimeout(() => r.lab.el.classList.remove("is-hot"), 1600);
615	    if (this.static) return;
616	    const idle = this.team.filter((m) => !m.task && !m.tasks.length);
617	    const who = idle.sort((a, b) => a.fig.position.distanceTo(r.centre) - b.fig.position.distanceTo(r.centre))[0];
618	    if (who) {
619	      const near = r.centre.clone().add(new THREE.Vector3(0.6, 0, 0.6));
620	      who.tasks.push({ type: "run", to: near }, { type: "face", to: r.centre }, { type: "point", t: 1.2 });
621	    }
622	  }
623	
624	  // Hurry, settle to plan view, and resolve when the board is still.
625	  async settle() {
626	    this.speed = 6;
627	    const s = this.current;
628	    if (s && !s.drawn) {
629	      await new Promise((r) => setTimeout(r, 700));
630	      s.rooms.forEach((x) => this._complete(x, true));
631	    }
632	    if (s) this._rise(s, true);
633	    await new Promise((resolve) => {
634	      if (this.static) { this.view.tilt = 0; resolve(); return; }
635	      const from = this.view.tilt;
636	      this._tween(950, (k) => { this.view.tilt = lerp(from, 0, ease(k)); }, resolve, { real: true });
637	    });
638	  }
639	
640	  /* ── animation plumbing ──────────────────────────────────────────── */
641	
642	  _fade(material, to, ms) {
643	    const from = material.opacity;
644	    this._tween(ms, (k) => { material.opacity = lerp(from, to, ease(k)); });
645	  }
646	
647	  _tween(ms, fn, done, { real = false } = {}) {
648	    (this.tweens ||= []).push({ t: 0, ms: Math.max(1, ms), fn, done, real });
649	  }
650	
651	  // Stop drawing frames while the stage is off screen.
652	  pause() { cancelAnimationFrame(this.raf); this.raf = 0; }
653	  resume() { if (!this.raf) { this.last = 0; this.raf = requestAnimationFrame(this._tick); } }
654	
655	  _tick(now) {
656	    this.raf = requestAnimationFrame(this._tick);
657	    const dt = Math.min(0.05, (now - (this.last || now)) / 1000);
658	    this.last = now;
659	    const step = dt * this.speed;
660	
661	    if (this.tweens?.length) {
662	      for (const tw of this.tweens) {
663	        tw.t += dt * 1000 * (tw.real ? 1 : Math.max(1, this.speed * 0.6));
664	        tw.fn(clamp(tw.t / tw.ms, 0, 1));
665	      }
666	      const done = this.tweens.filter((tw) => tw.t >= tw.ms);
667	      this.tweens = this.tweens.filter((tw) => tw.t < tw.ms);
668	      done.forEach((tw) => tw.done?.());
669	    }
670	
671	    if (!this.static) for (const m of this.team) this._member_tick(m, step, now);
672	
673	    this._placeCamera(now);
674	    this._frame();
675	    this.renderer.render(this.scene, this.camera);
676	    this._labelsTick();
677	  }
678	
679	  _member_tick(m, step, now) {
680	    const fig = m.fig;
681	    const u = fig.userData;
682	    if (!m.task) {
683	      m.task = m.tasks.shift() || null;
684	      if (!m.task && this.planningActive && this.construction.length) {
685	        // Keep working: take the next grid line.
686	        const [a, b] = this.construction.shift();
687	        m.tasks.push({ type: "run", to: a }, { type: "draw", pts: resample([a, b]), line: this._line([a, b], COL.chalk, 0.22, this.planning) });
688	        m.task = m.tasks.shift();
689	      }
690	      if (!m.task && this.planningActive && now > m.busyUntil) {
691	        // Pace the plot, looking it over.
692	        const { w, d, n } = this.plot;
693	        const to = this.P(Math.floor(Math.random() * n), 0.8 + Math.random() * (w - 1.6), 0.8 + Math.random() * (d - 1.6));
694	        m.tasks.push({ type: "run", to, slow: true }, { type: "wait", t: 0.8 + Math.random() * 1.2 });
695	        m.busyUntil = now + 2000;
696	      }
697	    }
698	
699	    let moving = false, drawing = false, pointing = false;
700	    const t = m.task;
701	    if (t) {
702	      if (t.type === "run") {
703	        const v = t.to.clone().sub(fig.position);
704	        v.y = 0;
705	        const dist = v.length();
706	        const sp = (t.slow ? RUN * 0.45 : RUN) * step;
707	        if (dist <= sp || dist < 0.02) { fig.position.set(t.to.x, 0, t.to.z); m.task = null; }
708	        else { fig.position.addScaledVector(v.normalize(), sp); m.face = Math.atan2(v.x, v.z); moving = true; }
709	      } else if (t.type === "draw") {
710	        t.i = (t.i ?? 0);
711	        const pace = (t.fast ? PACE * 3 : PACE) * step;
712	        t.acc = (t.acc ?? 0) + pace / 0.08;
713	        const before = t.i;
714	        while (t.acc >= 1 && t.i < t.pts.length - 1) { t.i++; t.acc -= 1; }
715	        const p = t.pts[t.i];
716	        if (t.i > before) {
717	          const q = t.pts[Math.max(0, t.i - 1)];
718	          m.face = Math.atan2(p.x - q.x, p.z - q.z);
719	        }
720	        fig.position.set(p.x, 0, p.z);
721	        t.line.geometry.setDrawRange(0, t.i + 1);
722	        drawing = true;
723	        if (t.i >= t.pts.length - 1) {
724	          if (t.room) this._complete(t.room);
725	          m.task = null;
726	        }
727	      } else if (t.type === "wait") {
728	        t.left = (t.left ?? t.t) - step;
729	        if (t.left <= 0) m.task = null;
730	      } else if (t.type === "point") {
731	        t.left = (t.left ?? t.t) - step;
732	        pointing = true;
733	        if (t.left <= 0) m.task = null;
734	      } else if (t.type === "face") {
735	        const v = t.to.clone().sub(fig.position);
736	        m.face = Math.atan2(v.x, v.z);
737	        m.task = null;
738	      } else if (t.type === "call") {
739	        t.fn();
740	        m.task = null;
741	      }
742	    }
743	
744	    // Turn toward travel, smoothly.
745	    let dy = m.face - fig.rotation.y;
746	    dy = Math.atan2(Math.sin(dy), Math.cos(dy));
747	    fig.rotation.y += dy * Math.min(1, step * 12);
748	
749	    // Gait: run, walk-and-draw, or stand.
750	    const freq = moving ? 11 : drawing ? 7 : 1.6;
751	    u.phase += step * freq;
752	    const swing = moving ? 0.85 : drawing ? 0.45 : 0;
753	    u.legL.rotation.x = Math.sin(u.phase) * swing;
754	    u.legR.rotation.x = -Math.sin(u.phase) * swing;
755	    u.armL.rotation.x = -Math.sin(u.phase) * swing * 0.8;
756	    u.body.position.y = moving ? Math.abs(Math.sin(u.phase)) * 0.045 : Math.sin(u.phase) * 0.004;
757	    u.body.rotation.x = moving ? 0.16 : drawing ? 0.28 : 0;
758	    // The working arm: down to the ground while drawing, up while pointing.
