// Usage: node server.mjs [port]   -> http://localhost:8080
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), 'site');
const PORT = +process.argv[2] || 8080;
const TYPES = {
  '.html': 'text/html; charset=utf-8', '.css': 'text/css', '.js': 'text/javascript', '.json': 'application/json',
  '.webmanifest': 'application/manifest+json', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg', '.gif': 'image/gif', '.webp': 'image/webp', '.ico': 'image/x-icon', '.mp4': 'video/mp4',
  '.woff': 'font/woff', '.woff2': 'font/woff2', '.txt': 'text/plain', '.xml': 'application/xml',
  '.avif': 'image/avif', '.gltf': 'model/gltf+json', '.bin': 'application/octet-stream',
};

function resolve(urlPath) {
  const p = path.normalize(decodeURIComponent(urlPath)).replace(/^(\.\.[/\\])+/, '');
  const full = path.join(ROOT, p);
  if (!full.startsWith(ROOT)) return null;
  for (const c of [full, path.join(full, 'index.html'), full + '.html']) {
    try { if (fs.statSync(c).isFile()) return c; } catch {}
  }
  return null;
}

http.createServer((req, res) => {
  const urlPath = new URL(req.url, 'http://x').pathname;
  let file = resolve(urlPath);
  let status = 200;
  if (!file) { file = path.join(ROOT, '404', 'index.html'); status = 404; }
  const type = TYPES[path.extname(file).toLowerCase()] || 'application/octet-stream';
  const size = fs.statSync(file).size;
  const range = req.headers.range;
  // Range support so videos can seek/scrub
  if (range && status === 200) {
    const [s, e] = range.replace('bytes=', '').split('-');
    const start = +s, end = e ? +e : size - 1;
    res.writeHead(206, { 'Content-Type': type, 'Content-Range': `bytes ${start}-${end}/${size}`, 'Accept-Ranges': 'bytes', 'Content-Length': end - start + 1 });
    fs.createReadStream(file, { start, end }).pipe(res);
    return;
  }
  res.writeHead(status, { 'Content-Type': type, 'Content-Length': size, 'Accept-Ranges': 'bytes', 'Cache-Control': 'no-cache' });
  if (req.method === 'HEAD') return res.end();
  fs.createReadStream(file).pipe(res);
  if (status === 404) console.log('404', urlPath);
}).listen(PORT, () => console.log(`Serving ${ROOT} at http://localhost:${PORT}`));
