135	function lightPadas(svg, plan) {
136	  if (!svg || !plan?.levels?.length) return { occupied: 0, sectors: [] };
137	  svg.querySelectorAll(".pada").forEach((p) => {
138	    p.setAttribute("fill", "transparent"); p.setAttribute("stroke", "#2E2517"); p.removeAttribute("data-lit");
139	  });
140	
141	  const rooms = plan.levels[0].rooms || [];
142	  if (!rooms.length) return { occupied: 0, sectors: [] };
143	
144	  let mnX = Infinity, mnY = Infinity, mxX = -Infinity, mxY = -Infinity;
145	  for (const rm of rooms) for (const [x, y] of rm.polygon || []) {
146	    mnX = Math.min(mnX, x); mxX = Math.max(mxX, x); mnY = Math.min(mnY, y); mxY = Math.max(mxY, y);
147	  }
148	  const w = mxX - mnX, h = mxY - mnY;
149	  if (!(w > 0 && h > 0)) return { occupied: 0, sectors: [] };
150	
151	  const dirOf = new Map((plan.room_summary || []).map((r) => [r.id, r.direction]));
152	  const sectors = [];
153	
154	  for (const rm of rooms) {
155	    const xs = (rm.polygon || []).map((p) => p[0]);
156	    const ys = (rm.polygon || []).map((p) => p[1]);
157	    if (!xs.length) continue;
158	    const dir = dirOf.get(rm.id) || "CENTRE";
159	    const pig = PIG[dir] || "chalk";
160	    sectors.push({ name: rm.name || cap(rm.type), dir, pig, area: rm.area });
161	
162	    const c0 = Math.floor(((Math.min(...xs) - mnX) / w) * 9);
163	    const c1 = Math.ceil(((Math.max(...xs) - mnX) / w) * 9);
164	    const r0 = Math.floor(((mxY - Math.max(...ys)) / h) * 9);   // +Y is north; SVG +Y is down
165	    const r1 = Math.ceil(((mxY - Math.min(...ys)) / h) * 9);
166	
167	    for (let r = Math.max(0, r0); r < Math.min(9, r1); r++)
168	      for (let c = Math.max(0, c0); c < Math.min(9, c1); c++) {
169	        const p = svg.querySelector(`.pada[data-r="${r}"][data-c="${c}"]`);
170	        if (p) { p.setAttribute("fill", HEX[pig]); p.setAttribute("fill-opacity", ".16"); p.setAttribute("data-lit", "1"); }
171	      }
172	  }
173	
174	  // The Brahmasthan is scored separately - a uniform wash over the centre
175	  // would hide the one rule the whole diagram exists to enforce.
176	  let occupied = 0;
177	  for (let r = 3; r < 6; r++) for (let c = 3; c < 6; c++) {
178	    const p = svg.querySelector(`.pada[data-r="${r}"][data-c="${c}"]`);
179	    if (!p) continue;
180	    if (p.getAttribute("data-lit")) {
181	      occupied++;
182	      p.setAttribute("fill", HEX.hingula); p.setAttribute("fill-opacity", ".34"); p.setAttribute("stroke", HEX.hingula);
183	    } else { p.setAttribute("stroke", "#9C9078"); }
184	  }
185	  return { occupied, sectors };
186	}
