/* the 3D tab */
.model-stage { position: relative; flex: 1 1 auto; min-height: 0; background: var(--ink); }
.v3-canvas { display: block; width: 100%; height: 100%; cursor: grab; }
.v3-canvas:active { cursor: grabbing; }
.model-cap { position: absolute; left: var(--gut); bottom: 18px; margin: 0; pointer-events: none; font-size: 10.5px; font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; color: var(--cream-3); }
.model-say { position: absolute; left: 50%; bottom: 52px; transform: translateX(-50%); width: min(640px, calc(100% - 48px)); margin: 0; text-align: center; pointer-events: none; font-family: var(--display); font-style: italic; font-weight: 300; font-stretch: 94%; font-size: 22px; line-height: 1.35; text-shadow: 0 2px 18px rgba(0, 0, 0, 0.9); }

/* ── overlays ────────────────────────────────────────────────────────── */

.sheetover { position: fixed; inset: 0; z-index: 80; display: grid; place-items: center; padding: 5vh 4vw; background: rgba(11, 10, 9, 0.82); backdrop-filter: blur(6px); animation: fade 0.3s var(--ease) both; }
@keyframes fade { from { opacity: 0; } }
.sheetover__panel { width: min(760px, 100%); max-height: 86vh; display: flex; flex-direction: column; border-radius: 16px; background: var(--coal); box-shadow: inset 0 0 0 1px var(--rule-2), 0 40px 100px rgba(0, 0, 0, 0.6); animation: lift 0.5s var(--ease) both; }
@keyframes lift { from { transform: translateY(18px); opacity: 0; } }
.sheetover__bar { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 22px 28px; border-bottom: 1px solid var(--rule); }
