.sheetover__body { overflow-y: auto; padding: 26px 28px 32px; }
.sheetover__body p { margin: 0 0 16px; max-width: 66ch; font-size: 15px; line-height: 1.75; color: var(--cream-2); }
.toast {
  position: fixed; left: 50%; bottom: 28px; z-index: 95; transform: translateX(-50%);
  display: flex; align-items: center; gap: 12px; max-width: min(92vw, 64ch); padding: 14px 20px; border-radius: 999px;
  font-size: 13px; background: var(--soot); color: var(--cream); box-shadow: inset 0 0 0 1px var(--rule-2), 0 18px 40px rgba(0, 0, 0, 0.55);
  animation: lift 0.4s var(--ease) both;
}
.toast::before { content: ""; width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; background: var(--brick); }

/* ── transitions between phases ──────────────────────────────────────── */

::view-transition-old(root) { animation: vt-out 0.28s cubic-bezier(0.4, 0, 1, 1) both; }
::view-transition-new(root) { animation: vt-in 0.6s var(--ease) both; }
::view-transition-group(sheet) { animation-duration: 0.8s; animation-timing-function: cubic-bezier(0.2, 0.75, 0.2, 1); }
::view-transition-old(sheet), ::view-transition-new(sheet) { height: 100%; object-fit: contain; }
::view-transition-group(bar) { animation-duration: 0.4s; }
@keyframes vt-out { to { opacity: 0; transform: scale(0.99); filter: blur(4px); } }
@keyframes vt-in { from { opacity: 0; transform: scale(1.01); filter: blur(6px); } }

/* The brief arrives once: headline lines rise into their lines. */
