  body[data-phase="compose"] .plotfig { animation: draw-in 1.4s var(--ease) 0.3s both; }
}
@keyframes rise { from { opacity: 0; transform: translateY(40%); clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 -10% 0); } }
@keyframes draw-in { from { opacity: 0; transform: translateY(12px); } }

/* ── smaller screens ─────────────────────────────────────────────────── */

@media (max-width: 1180px) {
