  .side { border-left: 0; border-top: 1px solid var(--rule); overflow: visible; }
  .bar { grid-template-columns: auto minmax(0, 1fr) auto; height: auto; min-height: var(--bar-h); padding-top: 10px; padding-bottom: 10px; row-gap: 6px; }
  body[data-phase="review"] .bar { position: sticky; }
  .views { grid-column: 1 / -1; order: 4; overflow-x: auto; justify-content: flex-start; }
  .bar__mid { justify-content: flex-start; overflow-x: auto; }
}
@media (max-width: 760px) {
  :root { --bar-h: 56px; }
