  empty.append(el("h2", "chat__hello", "What are we building?"),
    el("p", "chat__lede", "Tell me about the plot and the home you have in mind - in any language, as much or as little as you like. I'll ask about whatever matters and leave the rest to sensible defaults."));
  const cards = el("div", "suggest");
  for (const [title, text] of SUGGEST) {
    const c = el("button", "suggest__card"); c.type = "button";
    c.append(el("b", null, title), el("span", null, text));
    c.addEventListener("click", () => send(text));
    cards.append(c);
  }
  empty.append(cards);
  log.append(empty);

  const form = el("form", "composer");
  const input = el("textarea", "composer__in"); input.rows = 1; input.maxLength = 4000;
  input.placeholder = "Message Atri…";
  input.setAttribute("aria-label", "Message Atri");
  const sendBtn = el("button", "composer__send"); sendBtn.type = "submit"; sendBtn.disabled = true;
  sendBtn.setAttribute("aria-label", "Send");
  sendBtn.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  form.append(input, sendBtn);
  const hint = el("p", "composer__hint", "Enter to send · Shift + Enter for a new line");
  host.append(strip, log, form, hint);

  const scroll = () => { log.scrollTop = log.scrollHeight; };

  const renderFacts = () => {
    const b = state.brief;
    const bits = [];
    if (b.plot_width) bits.push(b.plot_unit === "ft"
      ? `${Math.round(b.plot_width / 0.3048)} × ${Math.round(b.plot_depth / 0.3048)} ft`
      : `${(+b.plot_width).toFixed(1)} × ${(+b.plot_depth).toFixed(1)} m`);
    if (b.road_direction) bits.push(`Road ${ROAD[b.road_direction] || b.road_direction}`);
    if (b.levels) bits.push(FLOORS(b.levels));
    if (b.bedrooms) bits.push(`${b.bedrooms} bed`);
    for (const a of b.amenities || []) bits.push(a.replace(/^\w/, (c) => c.toUpperCase()));
    for (const r of b.rooms || []) {
      if (r.level == null && !r.attach_to) continue;
      const name = r.type.replace(/_/g, " ");
      bits.push(`${name[0].toUpperCase()}${name.slice(1)}${r.level != null ? ` · ${r.level ? `L${r.level}` : "ground"}` : ""}`);
    }
    if (b.vastu && b.vastu !== "balanced") bits.push(`Vastu ${b.vastu}`);
    facts.replaceChildren(...(bits.length ? bits.map((t) => el("span", "fact", t)) : [el("span", "fact fact--empty", "Your brief will appear here as we talk")]));
    strip.classList.toggle("is-ready", state.ready);
    go.disabled = !state.ready;
  };
  renderFacts();

  const bubble = (who, text) => {
    empty.remove();
    const m = el("div", `msg msg--${who}`);
    if (who === "atri") m.append(el("span", "msg__av"));
    const body = el("div", "msg__body");
    body.textContent = text;
    m.append(body);
    log.append(m);
    scroll();
    return m;
  };

  // What the agent understood also goes into the sheet, so the drawing
  // beside the chat follows the conversation.
  const apply = (b) => {
    if (b.plot_width) setField("plot_width", (+b.plot_width).toFixed(1));
    if (b.plot_depth) setField("plot_depth", (+b.plot_depth).toFixed(1));
    if (b.road_direction) setField("road_direction", b.road_direction);
    if (b.levels) setField("levels", String(Math.min(4, b.levels)));
    if (b.bedrooms) setField("bedrooms", String(b.bedrooms));
    if (b.bathrooms || b.bedrooms) setField("bathrooms", String(b.bathrooms || b.bedrooms));
    if (b.vastu) setField("vastu", b.vastu);
    if (b.budget) setField("budget", String(Math.round(b.budget)));
    if (b.locality) setField("locality", b.locality);
    for (const a of b.amenities || []) setField(`amenity_${a.split(" ")[0]}`, true);
  };

  async function send(text, shown = text) {
    text = text.trim();
    if (state.busy || !text) return;
    state.busy = true; sendBtn.disabled = true;
    log.querySelectorAll(".quick").forEach((q) => q.remove());
    bubble("you", shown);
    const typing = el("div", "msg msg--atri msg--typing");
    typing.append(el("span", "msg__av"));
    const dots = el("div", "typing"); dots.innerHTML = "<i></i><i></i><i></i>";
    typing.append(dots); log.append(typing); scroll();
    try {
      const r = await fetch(`${API}/design/chat`, { method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: text, brief: state.brief, history: state.history }) });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const d = await r.json();
      typing.remove();
      state.brief = d.brief; state.ready = !!d.ready; state.request = d.request;
      state.history.push({ role: "user", text }, { role: "assistant", text: d.reply });
      apply(d.brief);
      renderFacts();
      const m = bubble("atri", d.reply);
      const opts = (d.questions || []).flatMap((q) => (q.options || []).slice(0, 5));
      if (opts.length) {
        const row = el("div", "quick");
        for (const o of opts) {
          const c = el("button", "quick__opt", o); c.type = "button";
          c.addEventListener("click", () => send(o));
          row.append(c);
        }
        m.append(row);
      }
      if (d.ready) {
        go.classList.remove("is-pulse"); void go.offsetWidth; go.classList.add("is-pulse");
      }
      scroll();
    } catch (err) {
      typing.remove();
      bubble("atri", `I couldn't reach the studio just now (${err.message}). Try again in a moment, or use the form.`);
    } finally {
      state.busy = false; sendBtn.disabled = !input.value.trim(); input.focus();
    }
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const v = input.value; input.value = ""; input.style.height = ""; sendBtn.disabled = true;
    send(v);
  });
  input.addEventListener("keydown", (e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); form.requestSubmit(); } });
  input.addEventListener("input", () => {
    input.style.height = "auto"; input.style.height = `${Math.min(180, input.scrollHeight)}px`;
    sendBtn.disabled = state.busy || !input.value.trim();
  });
  return { focus: () => input.focus() };
}

/* ═══ HOME v2: a conversation that reads like a product ═════════════════ */
.bar .engine { display: none; }
.wordmark span { font-family: var(--display); font-size: 17px; letter-spacing: 0.02em; text-transform: uppercase; color: #f1e9db; font-weight: 800; font-stretch: 100%; }
.wordmark span b { font-weight: 300; color: #cdb28c; margin-left: 0.28em; letter-spacing: 0.04em; }

.chat { grid-template-rows: auto minmax(0, 1fr) auto auto; gap: 12px; padding-bottom: 18px; }
.brief-strip { display: flex; align-items: center; gap: 12px; padding: 0 0 14px; border-bottom: 1px solid var(--rule); min-height: 46px; }
.brief-strip__facts { flex: 1; min-width: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.fact { padding: 5px 10px; border-radius: 999px; background: rgba(var(--c-rgb), 0.07); font-size: 12px; font-weight: 500; color: var(--cream); white-space: nowrap; animation: fact-in .4s var(--ease) both; }
.fact--empty { background: none; padding-left: 0; color: var(--cream-3); font-weight: 400; animation: none; }
.brief-strip__act { display: flex; align-items: center; gap: 4px; flex: none; }
.link-btn { padding: 6px 8px; border: 0; background: none; color: var(--cream-3); font: 500 12px var(--ui); cursor: pointer; }
.link-btn:hover { color: var(--cream); }
.btn--start { height: 36px; padding: 0 16px; margin-left: 6px; font-size: 12px; transition: opacity .2s var(--ease), transform .2s var(--ease); }
.btn--start:disabled { opacity: .28; cursor: not-allowed; }
.btn--start.is-pulse { animation: start-pulse 1.6s var(--ease) 2; }
@keyframes start-pulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(var(--c-rgb), 0.35); } 50% { box-shadow: 0 0 0 10px rgba(var(--c-rgb), 0); } }
@keyframes fact-in { from { opacity: 0; transform: translateY(4px); } }

.chat__log { gap: 22px; padding: 18px 2px 12px; }
.chat__empty { margin: auto 0; display: grid; gap: 14px; max-width: 620px; animation: msg-in .5s var(--ease) both; }
.chat__hello { margin: 0; font: 500 clamp(30px, 3.4vw, 46px)/1.02 var(--display); letter-spacing: -0.02em; color: var(--cream); }
.chat__lede { margin: 0; font-size: 15px; line-height: 1.6; color: var(--cream-2); max-width: 54ch; }
.suggest { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 10px; }
.suggest__card { display: grid; gap: 6px; align-content: start; padding: 14px; border: 1px solid var(--rule); border-radius: 14px; background: rgba(var(--c-rgb), 0.02); text-align: left; cursor: pointer; color: inherit; transition: border-color .2s var(--ease), background .2s var(--ease), transform .2s var(--ease); }
.suggest__card:hover { border-color: var(--rule-2); background: rgba(var(--c-rgb), 0.05); transform: translateY(-2px); }
.suggest__card b { font: 600 13px var(--ui); color: var(--cream); }
.suggest__card span { font-size: 12px; line-height: 1.5; color: var(--cream-3); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

.msg { max-width: 100%; display: grid; animation: msg-in .3s var(--ease) both; }
.msg--you { justify-self: end; max-width: 78%; padding: 10px 14px; border-radius: 18px 18px 6px 18px; background: rgba(var(--c-rgb), 0.1); }
.msg--you .msg__body { font-size: 14.5px; line-height: 1.55; color: var(--cream); white-space: pre-wrap; }
.msg--atri { grid-template-columns: 28px minmax(0, 1fr); column-gap: 12px; align-items: start; max-width: 92%; }
.msg__av { width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--rule-2); background: rgba(var(--c-rgb), 0.04) url("logo-arch.svg") center / 16px no-repeat; }
.msg--atri .msg__body { padding-top: 3px; font-size: 15px; line-height: 1.65; color: var(--cream); white-space: pre-wrap; }
.quick { grid-column: 2; display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.quick__opt { padding: 7px 13px; border: 1px solid var(--rule-2); border-radius: 999px; background: transparent; color: var(--cream-2); font: 500 12.5px var(--ui); cursor: pointer; transition: background .15s, color .15s, border-color .15s; }
.quick__opt:hover { background: var(--cream); color: var(--ink); border-color: var(--cream); }
.typing { display: inline-flex; gap: 5px; padding: 10px 0; }
.typing i { width: 6px; height: 6px; border-radius: 50%; background: var(--cream-3); animation: dot 1.1s var(--ease) infinite; }
.typing i:nth-child(2) { animation-delay: .15s; } .typing i:nth-child(3) { animation-delay: .3s; }

.composer { display: flex; align-items: flex-end; gap: 10px; padding: 8px 8px 8px 18px; border: 1px solid var(--rule-2); border-radius: 22px; background: #121110; transition: border-color .2s var(--ease), box-shadow .2s var(--ease); }
.composer:focus-within { border-color: rgba(var(--c-rgb), 0.45); box-shadow: 0 0 0 4px rgba(var(--c-rgb), 0.04); }
.composer__in { flex: 1; min-height: 26px; max-height: 180px; padding: 9px 0; resize: none; border: 0; background: transparent; color: var(--cream); font: 400 15px/1.5 var(--ui); outline: none; }
.composer__in::placeholder { color: var(--cream-3); }
.composer__send { flex: none; width: 38px; height: 38px; border: 0; border-radius: 50%; background: var(--cream); color: var(--ink); cursor: pointer; display: grid; place-items: center; transition: opacity .2s, transform .2s var(--ease); }
.composer__send svg { width: 18px; height: 18px; }
.composer__send:not(:disabled):hover { transform: translateY(-1px); }
.composer__send:disabled { opacity: .25; cursor: default; }
.composer__hint { margin: 0; text-align: center; font-size: 11px; color: var(--cream-3); }
@media (max-width: 900px) { .suggest { grid-template-columns: minmax(0, 1fr); } .brief-strip { flex-wrap: wrap; } }

